def _ensure_nofile_limit() -> None:
    """Best-effort increase process NOFILE soft limit to avoid Errno 24 under long runs."""
    try:
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    except Exception:
        return
    target_raw = str(os.environ.get("PM_NOFILE_SOFT", "8192") or "").strip()
    try:
        target = int(float(target_raw))
    except Exception:
        target = 8192
    if target <= 0:
        return
    upper = hard if isinstance(hard, int) and hard > 0 else soft
    if not isinstance(upper, int) or upper <= 0:
        return
    desired = max(int(soft or 0), min(target, upper))
    if desired <= int(soft or 0):
        return
    try:
        resource.setrlimit(resource.RLIMIT_NOFILE, (desired, hard))
        print(f"[fd_limit] RLIMIT_NOFILE soft {soft} -> {desired} (hard={hard})")
    except Exception:
        pass


_ensure_nofile_limit()

