    global MINUTE_EDGE_ENTRY_YES_TOP_EDGE_MIN
    global MINUTE_EDGE_ENTRY_YES_TOP_REQUIRE_ASK_MIN, MINUTE_EDGE_ENTRY_YES_TOP_ASK_MIN
    global MINUTE_EDGE_ENTRY_YES_TOP_MODEL_CONSENSUS_MIN
    global MINUTE_EDGE_ENTRY_YES_TOP_PRICE_SPREAD_RATIO
    global MINUTE_EDGE_ENTRY_YES_TOP_PRICE_SPREAD_RATIO_STRONG
    global MINUTE_EDGE_ENTRY_YES_TOP_PRICE_TAKE_EDGE_MIN
    global MINUTE_EDGE_ENTRY_YES_TOP_TREND_STRENGTH_MIN
