    global MINUTE_EDGE_ENTRY_EDGE_BAND_ENABLED
    global MINUTE_EDGE_ENTRY_EDGE_BAND_1_MIN, MINUTE_EDGE_ENTRY_EDGE_BAND_1_MAX
    global MINUTE_EDGE_ENTRY_EDGE_BAND_2_MIN, MINUTE_EDGE_ENTRY_EDGE_BAND_2_MAX
    global MINUTE_EDGE_ENTRY_EDGE_BAND_3_MIN, MINUTE_EDGE_ENTRY_EDGE_BAND_3_MAX
    global MINUTE_EDGE_ENTRY_EDGE_BANDS
    global MINUTE_EDGE_ENTRY_Q_BAND_ENABLED
    global MINUTE_EDGE_ENTRY_Q_BAND_1_MIN, MINUTE_EDGE_ENTRY_Q_BAND_1_MAX
    global MINUTE_EDGE_ENTRY_Q_BAND_2_MIN, MINUTE_EDGE_ENTRY_Q_BAND_2_MAX
    global MINUTE_EDGE_ENTRY_Q_BAND_3_MIN, MINUTE_EDGE_ENTRY_Q_BAND_3_MAX
    global MINUTE_EDGE_ENTRY_Q_BANDS
    global MINUTE_EDGE_ENTRY_CONFIDENCE_MIN, MINUTE_EDGE_ENTRY_BIAS_MIN
    global MINUTE_EDGE_ENTRY_BIAS_DAYS, MINUTE_EDGE_ENTRY_REQUIRE_CONFIDENCE
    global MINUTE_EDGE_ENTRY_REQUIRE_BIAS, MINUTE_EDGE_ENTRY_APPLY_BIAS
    global AUTO_TRADE_EDGE_NEVER_MIN, AUTO_TRADE_EDGE_NEVER_MAX
    global AUTO_TRADE_EDGE_BUY_MIN, AUTO_TRADE_EDGE_BUY_MAX
    global AUTO_TRADE_YES_Q_NEVER_MIN, AUTO_TRADE_YES_Q_NEVER_MAX
    global AUTO_TRADE_NO_ASK_MIN, AUTO_TRADE_NO_ASK_MAX
    global AUTO_TRADE_YES_OVERPRICE_MIN, AUTO_TRADE_ENTRY_DEPTH_MULT
    global EDGE_VWAP_DEPTH_MULT
    global MINUTE_EDGE_L_MAX, MINUTE_EDGE_L_EXIT, MINUTE_EDGE_FLIP_MIN_EDGE
    global MINUTE_EDGE_L_EXIT_CONSEC
    global AUTO_TRADE_REENTRY_COOLDOWN_SEC, AUTO_TRADE_MIN_HOLD_SEC
    global AUTO_TRADE_TEMPERATURE_EVENT_MIN_EDGE_SCORE_DISPLAY
    global AUTO_TRADE_TEMPERATURE_EVENT_MIN_EDGE_SCORE_ENTRY
    global MINUTE_EDGE_HEADROOM_EXIT
    path = AUTO_TRADE_CONFIG_PATH
    try:
        stat = path.stat()
    except FileNotFoundError:
        return
    mtime = stat.st_mtime
    if _AUTO_TRADE_CONFIG_MTIME is not None and mtime <= _AUTO_TRADE_CONFIG_MTIME:
        return
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        _AUTO_TRADE_CONFIG_MTIME = mtime
        return
    if not isinstance(payload, dict):
        _AUTO_TRADE_CONFIG_MTIME = mtime
        return
    legacy_edge_keys = {
        "entry_edge_min": "entry_signal_edge_min",
        "entry_edge_min_consecutive": "entry_signal_edge_min_consecutive",
        "entry_require_edge_min": "entry_require_signal_edge",
        "entry_yes_top_edge_min": "entry_yes_top_signal_edge_min",
        "entry_yes_top_price_take_edge_min": "entry_yes_top_price_take_signal_edge_min",
        "entry_trade_edge_min": "entry_signal_edge_min",
        "entry_trade_edge_min_consecutive": "entry_signal_edge_min_consecutive",
        "entry_require_trade_edge": "entry_require_signal_edge",
        "entry_yes_top_trade_edge_min": "entry_yes_top_signal_edge_min",
        "entry_yes_top_price_take_trade_edge_min": "entry_yes_top_price_take_signal_edge_min",
    }
    for legacy_key, new_key in legacy_edge_keys.items():
        if new_key not in payload and legacy_key in payload:
            payload[new_key] = payload.get(legacy_key)
        if legacy_key in payload:
            payload.pop(legacy_key, None)
    legacy_weather_keys = {
        "weather_spread_max": "entry_spread_max",
        "weather_reverse_confirm_count": "exit_lag_consecutive",
        "weather_token_cooldown_sec": "reentry_cooldown_sec",
        "weather_min_hold_sec": "min_hold_sec",
    }
    for legacy_key, new_key in legacy_weather_keys.items():
        if new_key not in payload and legacy_key in payload:
            payload[new_key] = payload.get(legacy_key)
        if legacy_key in payload:
            payload.pop(legacy_key, None)
    if "entry_time_thresholds" in payload:
        tiers_raw = payload.get("entry_time_thresholds")
        if isinstance(tiers_raw, list):
            tiers = []
            for item in tiers_raw:
                if not isinstance(item, dict):
                    continue
                max_days = item.get("max_days")
                try:
                    max_days_val = int(max_days) if max_days is not None else None
                except (TypeError, ValueError):
                    max_days_val = None
                if max_days_val is None:
                    continue
                edge_min = to_float(item.get("edge_score_min"))
                signal_min = to_float(item.get("entry_signal_edge_min"))
                if edge_min is None and signal_min is None:
                    continue
                tiers.append(
                    {
                        "max_days": max_days_val,
                        "edge_score_min": edge_min,
                        "entry_signal_edge_min": signal_min,
                    }
                )
            if tiers:
                tiers.sort(key=lambda t: int(t.get("max_days") or 0))
                os.environ["PM_AUTO_TRADE_ENTRY_TIME_THRESHOLDS"] = json.dumps(tiers, ensure_ascii=True)
    if "order_usdc_tiers" in payload:
        tiers_raw = payload.get("order_usdc_tiers")
        if isinstance(tiers_raw, list):
            tiers = []
            for item in tiers_raw:
                if not isinstance(item, dict):
                    continue
                order_usdc = to_float(item.get("order_usdc"))
                if order_usdc is None or not math.isfinite(order_usdc) or order_usdc <= 0:
                    continue
                min_edge_score = to_float(item.get("min_edge_score"))
                min_edge_conf = to_float(item.get("min_edge_confidence"))
                tiers.append(
                    {
                        "order_usdc": float(order_usdc),
                        "min_edge_score": min_edge_score,
                        "min_edge_confidence": min_edge_conf,
                    }
                )
            if tiers:
                tiers.sort(key=lambda t: float(t.get("order_usdc") or 0.0))
                os.environ["PM_AUTO_TRADE_ORDER_USDC_TIERS"] = json.dumps(tiers, ensure_ascii=True)

    def _apply_float(key: str, env_key: str, target: Optional[str] = None, min_val: Optional[float] = None) -> None:
        if key not in payload:
            return
        raw = payload.get(key)
        try:
            val = float(raw) if raw is not None else None
        except (TypeError, ValueError):
            return
        if val is None or not math.isfinite(val):
            return
        if min_val is not None and val < min_val:
            return
        os.environ[env_key] = f"{val:.6g}"
        if target:
            globals()[target] = val

    def _apply_float_nullable(
        key: str,
        env_key: str,
        target: Optional[str] = None,
        min_val: Optional[float] = None,
        default_val: float = 0.0,
    ) -> None:
        if key not in payload:
            return
        raw = payload.get(key)
        if raw is None:
            os.environ[env_key] = f"{default_val:.6g}"
            if target:
                globals()[target] = default_val
            return
        try:
            val = float(raw)
        except (TypeError, ValueError):
            return
        if not math.isfinite(val):
            return
        if min_val is not None and val < min_val:
            return
        os.environ[env_key] = f"{val:.6g}"
        if target:
            globals()[target] = val

    def _apply_bool(key: str, env_key: str) -> None:
        if key not in payload:
            return
        flag = bool(payload.get(key))
        os.environ[env_key] = "1" if flag else "0"

    def _apply_choice(key: str, env_key: str, choices: Set[str]) -> None:
        if key not in payload:
            return
        value = str(payload.get(key) or "").strip().lower()
        if value not in choices:
            return
        os.environ[env_key] = value

    def _apply_json(key: str, env_key: str) -> None:
        if key not in payload:
            return
        raw = payload.get(key)
        if raw is None:
            os.environ.pop(env_key, None)
            return
        obj = None
        if isinstance(raw, (dict, list)):
            obj = raw
        elif isinstance(raw, str):
            text = raw.strip()
            if not text:
                os.environ.pop(env_key, None)
                return
            try:
                parsed = json.loads(text)
            except Exception:
                return
            if isinstance(parsed, (dict, list)):
                obj = parsed
        if obj is None:
            return
        os.environ[env_key] = json.dumps(obj, ensure_ascii=True, separators=(",", ":"))

    def _apply_int(
        key: str,
        env_key: str,
        min_val: Optional[int] = None,
        target: Optional[str] = None,
    ) -> None:
        if key not in payload:
            return
        raw = payload.get(key)
        try:
            val = int(raw) if raw is not None else None
        except (TypeError, ValueError):
            return
        if val is None:
            return
        if min_val is not None and val < min_val:
            return
        os.environ[env_key] = str(val)
        if target:
            globals()[target] = val

    _apply_float("edge_score_min", "PM_AUTO_TRADE_MIN_EDGE_SCORE", "AUTO_TRADE_MIN_EDGE_SCORE", 0)
