    _apply_float("entry_ask_max", "PM_AUTO_TRADE_ENTRY_ASK_MAX", "MINUTE_EDGE_ENTRY_ASK_MAX", 0)
    _apply_float("entry_min_outcome_volume", "PM_AUTO_TRADE_ENTRY_MIN_OUTCOME_VOLUME", None, 0)
