def to_float(value: Optional[float]) -> Optional[float]:
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _get_outcome_volume_value(row: Mapping[str, Any]) -> Optional[float]:
    for key in ("outcome_volume", "volume_24h", "volume_total"):
        val = to_float(row.get(key))
        if val is None or not math.isfinite(val):
            continue
        return val
    return None


def _entry_outcome_volume_ok(
    row: Mapping[str, Any], threshold: Optional[float]
) -> Tuple[bool, Optional[float], str]:
    if threshold is None or threshold <= 0:
        return True, None, ""
    volume_val = _get_outcome_volume_value(row)
    if volume_val is None:
        return False, None, "missing"
    if volume_val < threshold:
        return False, volume_val, "below"
    return True, volume_val, ""


def _normalize_outcome_key(value: Any) -> str:
    text = str(value or "").strip().lower()
    if not text:
        return ""
    return " ".join(text.split())


def _build_outcome_volume_lookup(outcome_tokens: Iterable[Mapping[str, Any]]) -> Dict[str, float]:
    lookup: Dict[str, float] = {}
    single_values: List[float] = []
    for item in outcome_tokens:
        if not isinstance(item, Mapping):
            continue
        volume_val = _get_outcome_volume_value(item)
        if volume_val is None or not math.isfinite(volume_val):
            continue
        label = str(item.get("label") or "").strip()
        if label:
            lookup[label] = volume_val
            normalized = _normalize_outcome_key(label)
            if normalized:
                lookup[normalized] = volume_val
        single_values.append(volume_val)
    if len(single_values) == 1:
        lookup["__single__"] = single_values[0]
    return lookup


def _coerce_q_raw(q: Dict[str, Any]) -> Optional[float]:
    val = to_float(q.get("q_raw"))
    if val is not None:
        return val
    return to_float(q.get("q_round"))


def _env_float_default(key: str, default: float) -> float:
    val = to_float(os.environ.get(key))
    if val is None or not math.isfinite(val):
        return float(default)
    return float(val)


def _env_int_default(key: str, default: int) -> int:
    raw = os.environ.get(key)
    if raw is None:
        return int(default)
    try:
        val = int(raw)
    except (TypeError, ValueError):
        return int(default)
    if val < 1:
        return int(default)
    return int(val)


def _env_bool(key: str, default: bool = False) -> bool:
    raw = os.environ.get(key)
    if raw is None:
        return default
    return str(raw).strip().lower() in {"1", "true", "yes", "on"}


