def _resolve_entry_edge_bands() -> List[Tuple[float, float]]:
    bands: List[Tuple[float, float]] = []
    pairs = (
        (MINUTE_EDGE_ENTRY_EDGE_BAND_1_MIN, MINUTE_EDGE_ENTRY_EDGE_BAND_1_MAX),
        (MINUTE_EDGE_ENTRY_EDGE_BAND_2_MIN, MINUTE_EDGE_ENTRY_EDGE_BAND_2_MAX),
        (MINUTE_EDGE_ENTRY_EDGE_BAND_3_MIN, MINUTE_EDGE_ENTRY_EDGE_BAND_3_MAX),
    )
    for min_val, max_val in pairs:
        if min_val == 0 and max_val == 0:
            continue
        if not math.isfinite(min_val) or not math.isfinite(max_val):
            continue
        if min_val < 0 or max_val < 0:
            continue
        if min_val > max_val:
            continue
        bands.append((min_val, max_val))
    return bands

MINUTE_EDGE_ENTRY_EDGE_BANDS = _resolve_entry_edge_bands()
