EDGE_BIAS_CALIBRATION: List[Tuple[float, float, Optional[float], Optional[float]]] = []
EDGE_BIAS_CALIBRATION_DAYS: Optional[int] = None
EDGE_BIAS_CACHE_MTIME: Optional[float] = None
EDGE_BIAS_CALIBRATION_RUN_ID: Optional[int] = None
EDGE_BIAS_CALIBRATION_LOADED_AT: float = 0.0
EDGE_BIAS_CALIBRATION_TTL_SEC: float = 300.0


def _load_edge_bias_calibration(days: int) -> None:
    global EDGE_BIAS_CALIBRATION
    global EDGE_BIAS_CALIBRATION_DAYS
    global EDGE_BIAS_CACHE_MTIME
    global EDGE_BIAS_CALIBRATION_RUN_ID
    global EDGE_BIAS_CALIBRATION_LOADED_AT
    global EDGE_BIAS_CALIBRATION_TTL_SEC
    if not days or days <= 0:
        EDGE_BIAS_CALIBRATION = []
        EDGE_BIAS_CALIBRATION_DAYS = days
        EDGE_BIAS_CALIBRATION_RUN_ID = None
        EDGE_BIAS_CALIBRATION_LOADED_AT = time.time()
        return
    # Allow tuning reload cadence without restarting long-running processes.
    try:
        ttl = float(os.environ.get("PM_EDGE_BIAS_CALIBRATION_TTL_SEC", str(EDGE_BIAS_CALIBRATION_TTL_SEC)) or 300.0)
        if math.isfinite(ttl) and ttl > 0:
            EDGE_BIAS_CALIBRATION_TTL_SEC = ttl
    except Exception:
        pass
    now_ts = time.time()
    if (
        EDGE_BIAS_CALIBRATION_DAYS == days
        and EDGE_BIAS_CALIBRATION
        and EDGE_BIAS_CALIBRATION_LOADED_AT > 0
        and (now_ts - EDGE_BIAS_CALIBRATION_LOADED_AT) <= EDGE_BIAS_CALIBRATION_TTL_SEC
    ):
        return

    # Prefer SSOT from SQLite (data/archive.db). Fallback to legacy JSON cache only if DB has no bins.
    try:
        if DB_PATH.exists():
            init_db()
            conn = open_db()
            cur = conn.cursor()
            cur.execute(
                """
                SELECT id
                FROM edge_bias_calibration_runs
                WHERE days = ? AND ok = 1
                ORDER BY created_at DESC, id DESC
                LIMIT 1
                """,
                (int(days),),
            )
            row = cur.fetchone()
            run_id = int(row[0]) if row and row[0] is not None else None
            bins: List[Tuple[float, float, Optional[float], Optional[float]]] = []
            if run_id is not None:
                cur.execute(
                    """
                    SELECT low, high, bias_mean, ratio, count
                    FROM edge_bias_calibration_bins
                    WHERE run_id = ? AND basis = 'event'
                    ORDER BY bin_index ASC
                    """,
                    (int(run_id),),
                )
                for low, high, bias_mean, ratio, count in cur.fetchall() or []:
                    try:
                        count_i = int(count or 0)
                    except Exception:
                        count_i = 0
                    if count_i <= 0:
                        continue
                    low_f = to_float(low)
                    high_f = to_float(high)
                    if low_f is None or high_f is None or not math.isfinite(low_f) or not math.isfinite(high_f):
                        continue
                    bins.append((float(low_f), float(high_f), to_float(bias_mean), to_float(ratio)))
            conn.close()
            if bins:
                EDGE_BIAS_CALIBRATION = bins
                EDGE_BIAS_CALIBRATION_DAYS = days
                EDGE_BIAS_CALIBRATION_RUN_ID = run_id
                EDGE_BIAS_CALIBRATION_LOADED_AT = now_ts
                # Clear legacy file mtime cache so DB remains source of truth.
                EDGE_BIAS_CACHE_MTIME = None
                return
    except Exception:
        # Fall back to legacy file cache below.
        pass
    try:
        stat = EDGE_BIAS_CACHE_PATH.stat()
    except FileNotFoundError:
        EDGE_BIAS_CALIBRATION = []
        EDGE_BIAS_CALIBRATION_DAYS = days
        EDGE_BIAS_CACHE_MTIME = None
        EDGE_BIAS_CALIBRATION_RUN_ID = None
        EDGE_BIAS_CALIBRATION_LOADED_AT = now_ts
        return
    mtime = stat.st_mtime
    if EDGE_BIAS_CACHE_MTIME is not None and EDGE_BIAS_CACHE_MTIME >= mtime and EDGE_BIAS_CALIBRATION_DAYS == days:
        return
    try:
        raw = EDGE_BIAS_CACHE_PATH.read_text(encoding="utf-8")
        cached = json.loads(raw)
    except (OSError, json.JSONDecodeError):
        EDGE_BIAS_CALIBRATION = []
        EDGE_BIAS_CALIBRATION_DAYS = days
        EDGE_BIAS_CACHE_MTIME = mtime
        return
    if not isinstance(cached, dict):
        EDGE_BIAS_CALIBRATION = []
        EDGE_BIAS_CALIBRATION_DAYS = days
        EDGE_BIAS_CACHE_MTIME = mtime
        return
    by_days = cached.get("by_days") if isinstance(cached.get("by_days"), dict) else cached
    entry = None
    if isinstance(by_days, dict):
        entry = by_days.get(str(days)) or by_days.get(days)
        if entry is None and by_days:
            entry = next(iter(by_days.values()))
    payload = entry.get("payload") if isinstance(entry, dict) else None
    if not isinstance(payload, dict):
        payload = entry if isinstance(entry, dict) else None
    basis_payload = None
    if isinstance(payload, dict):
        basis_payload = payload.get("event_basis")
        if not isinstance(basis_payload, dict):
            basis_payload = payload
    calib = None
    if isinstance(basis_payload, dict):
        calib = basis_payload.get("calibration")
        if isinstance(calib, dict):
            calib = calib.get("bins")
    if not isinstance(calib, list):
        EDGE_BIAS_CALIBRATION = []
        EDGE_BIAS_CALIBRATION_DAYS = days
        EDGE_BIAS_CACHE_MTIME = mtime
        EDGE_BIAS_CALIBRATION_RUN_ID = None
        EDGE_BIAS_CALIBRATION_LOADED_AT = now_ts
        return
    bins: List[Tuple[float, float, Optional[float], Optional[float]]] = []
    for row in calib:
        if not isinstance(row, dict):
            continue
        count = int(row.get("count") or 0)
        if count <= 0:
            continue
        rng = row.get("range") or []
        if not isinstance(rng, list) or len(rng) < 2:
            continue
        low = to_float(rng[0])
        high = to_float(rng[1])
        if low is None or high is None or not math.isfinite(low) or not math.isfinite(high):
            continue
        bias_mean = to_float(row.get("bias_mean"))
        ratio = to_float(row.get("ratio"))
        bins.append((float(low), float(high), bias_mean, ratio))
    EDGE_BIAS_CALIBRATION = bins
    EDGE_BIAS_CALIBRATION_DAYS = days
    EDGE_BIAS_CACHE_MTIME = mtime
    EDGE_BIAS_CALIBRATION_RUN_ID = None
    EDGE_BIAS_CALIBRATION_LOADED_AT = now_ts


def _resolve_edge_bias(pred_edge_points: Optional[float]) -> Tuple[Optional[float], Optional[float]]:
    if pred_edge_points is None or not math.isfinite(pred_edge_points):
        return None, None
    if not EDGE_BIAS_CALIBRATION:
        return None, None
    last_idx = len(EDGE_BIAS_CALIBRATION) - 1
    for idx, (low, high, bias_mean, ratio) in enumerate(EDGE_BIAS_CALIBRATION):
        if pred_edge_points >= low and (pred_edge_points < high or idx == last_idx):
            return bias_mean, ratio
    return None, None
