def _edge_realizable_report_bucket_map(report: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    out: Dict[str, Dict[str, Any]] = {}
    if not isinstance(report, dict):
        return out
    buckets = report.get("buckets")
    if not isinstance(buckets, list):
        return out
    for entry in buckets:
        if not isinstance(entry, dict):
            continue
        key = str(entry.get("bucket") or "").strip()
        if not key:
            continue
        out[key] = entry
    return out


def _edge_strategy_gate_map(report: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    out: Dict[str, Dict[str, Any]] = {}
    if not isinstance(report, dict):
        return out
    by_map = report.get("by_strategy_map")
    if isinstance(by_map, dict):
        for key, entry in by_map.items():
            name = str(key or "").strip().lower()
            if not name or not isinstance(entry, dict):
                continue
            out[name] = dict(entry)
        if out:
            return out
    by_list = report.get("by_strategy")
    if not isinstance(by_list, list):
        return out
    for entry in by_list:
        if not isinstance(entry, dict):
            continue
        name = str(entry.get("strategy") or "").strip().lower()
        if not name:
            continue
        out[name] = dict(entry)
    return out


def _load_recent_outcome_history(
    slug: str,
    event_date: str,
    limit: int,
) -> Dict[str, Dict[str, List]]:
    if not slug or not event_date or limit <= 0:
        return {}
    if not DB_PATH.exists():
        return {}
    date_key = event_date.split("T", 1)[0]
    history_limit = max(limit * 50, TIME_EDGE_HISTORY_ROWS)
    try:
        conn = open_db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute(
            """
            SELECT payload_json, created_at
            FROM event_runs
            WHERE slug = ? AND event_date = ?
            ORDER BY created_at DESC
            LIMIT ?
            """,
            (slug, date_key, history_limit),
        )
        rows = cur.fetchall()
    except Exception:
        return {}
    finally:
        try:
            conn.close()
        except Exception:
            pass
    history: Dict[str, Dict[str, List]] = {}
    for row in reversed(rows):
        payload_raw = row["payload_json"]
        if not payload_raw:
            continue
        created_at = str(row["created_at"] or "")
        try:
            payload = json.loads(payload_raw)
        except json.JSONDecodeError:
            continue
        dist = payload.get("rows") or []
        prov_raw = payload.get("model_provenance") or {}
        has_update = True
        if isinstance(prov_raw, dict) and prov_raw:
            has_update = False
            for entry in prov_raw.values():
                if not isinstance(entry, dict):
                    has_update = True
                    break
                status = str(entry.get("status") or "").lower()
                if not status or status not in ("cache_hit", "skipped"):
                    has_update = True
                    break
        for entry in dist:
            outcome = str(entry.get("outcome") or "")
            if not outcome:
                continue
            q_val = to_float(entry.get("q_round"))
            q_cal_val = to_float(entry.get("q_calibrated"))
            if q_val is None:
                continue
            prev_q = None
            if outcome in history:
                series = history[outcome].get("q_round")
                if series:
                    prev_q = series[-1]
            per_model_raw = entry.get("per_model_q") or {}
            per_model = {}
            for model, band in per_model_raw.items():
                band = band or {}
                dir_value = to_float(band.get("dir_value"))
                if dir_value is None:
                    dir_value = to_float(band.get("q_round"))
                if dir_value is None:
                    continue
                per_model[str(model)] = dir_value
            skip_q = (
                not has_update
                and prev_q is not None
                and abs(q_val - prev_q) < TIME_EDGE_Q_EPS
            )
            bucket = history.setdefault(
                outcome,
                {
                    "q_round": [],
                    "q_min": [],
                    "q_max": [],
                    "q_calibrated": [],
                    "best_ask": [],
                    "best_ask_no": [],
                    "best_bid": [],
                    "best_bid_no": [],
                    "yes_price": [],
                    "no_price": [],
                    "per_model_q": [],
                    "ts": [],
                },
            )
            if not skip_q:
                bucket["q_round"].append(q_val)
                bucket["q_min"].append(to_float(entry.get("q_min")))
                bucket["q_max"].append(to_float(entry.get("q_max")))
                bucket["q_calibrated"].append(q_cal_val)
            bucket["best_ask"].append(to_float(entry.get("best_ask")))
            bucket["best_ask_no"].append(to_float(entry.get("best_ask_no")))
            bucket["best_bid"].append(to_float(entry.get("best_bid")))
            bucket["best_bid_no"].append(to_float(entry.get("best_bid_no")))
            bucket["yes_price"].append(to_float(entry.get("yes_price")))
            bucket["no_price"].append(to_float(entry.get("no_price")))
            bucket["ts"].append(created_at)
            if not skip_q:
                bucket["per_model_q"].append(per_model)
    return history


def _time_edge_delta_sum(values: List[float], lookback: int = TIME_EDGE_LOOKBACK) -> float:
    if len(values) < lookback:
        return 0.0
    seq = values[-lookback:]
    if len(seq) < 3:
        return 0.0
    d1 = seq[-2] - seq[-3]
    d2 = seq[-1] - seq[-2]
    mag = abs(d1) + abs(d2)
    if mag <= 0:
        return 0.0
    dir_score = 0.5 * (1.0 + math.tanh(TIME_EDGE_DIR_K * d1 * d2))
    return mag * dir_score


def _direction_base(delta: Optional[float], scale: float = TIME_EDGE_BASE_SCALE) -> float:
    if delta is None:
        return 0.0
    if scale <= 0:
        return 0.0
    try:
        x = float(delta) / scale
    except (TypeError, ValueError):
        return 0.0
    if x >= 20:
        return 1.0
    if x <= -20:
        return 0.0
    return 1.0 / (1.0 + math.exp(-x))


def _liquidity_factor(model_spread: Optional[float]) -> float:
    if model_spread is None:
        return 0.0
    try:
        spread = float(model_spread)
    except (TypeError, ValueError):
        return 0.0
    if spread <= 0:
        return 0.0
    return max(0.0, min(spread / 0.10, 1.0))


def _headroom_min(market_var: Optional[str]) -> float:
    if str(market_var or "").startswith("temperature"):
        return HEADROOM_MIN_TEMP
    return HEADROOM_MIN_BINARY


def _lag_factor(
    ask: Optional[float],
    bid: Optional[float],
    spread: Optional[float],
    mid_price: Optional[float],
) -> Optional[float]:
    if ask is None or spread is None or spread <= 0:
        return None
    mid = mid_price
    if mid is None:
        if bid is None:
            return None
        mid = (ask + bid) / 2.0
    return (ask - mid) / spread


def _lag_consecutive_hit(
    current_lag: Optional[float],
    threshold: float,
    steps: int,
    ask_hist: List[Optional[float]],
    bid_hist: List[Optional[float]],
    price_hist: List[Optional[float]],
) -> bool:
    if current_lag is None or current_lag <= threshold:
        return False
    if steps <= 1:
        return True
    needed = steps - 1
    if not ask_hist or not bid_hist or not price_hist:
        return False
    for offset in range(1, needed + 1):
        if len(ask_hist) < offset or len(bid_hist) < offset or len(price_hist) < offset:
            return False
        ask = ask_hist[-offset]
        bid = bid_hist[-offset]
        price = price_hist[-offset]
        spread = None
        if ask is not None and bid is not None:
            spread = float(ask) - float(bid)
        lag_val = _lag_factor(ask, bid, spread, price)
        if lag_val is None or lag_val <= threshold:
            return False
    return True


def _price_mid(bid: Optional[float], ask: Optional[float]) -> Optional[float]:
    if bid is None and ask is None:
        return None
    if bid is None:
        return ask
    if ask is None:
        return bid
    return (bid + ask) / 2.0


def _trend_down_from_series(
    series: List[float],
    lookback: int,
    min_move: float,
    min_consistency: float,
) -> Tuple[Optional[float], Optional[float], bool]:
    if lookback < 2:
        lookback = 2
    if not series:
        return None, None, False
    if len(series) >= lookback:
        points = series[-lookback:]
    else:
        points = series[:]
    if len(points) < 2:
        return None, None, False
    first = points[0]
    last = points[-1]
    if first is None or not math.isfinite(first) or first <= 0:
        return None, None, False
    pct = last / first - 1.0
    steps = len(points) - 1
    down_steps = 0
    for idx in range(steps):
        prev = points[idx]
        cur = points[idx + 1]
        if cur < prev - TIME_EDGE_Q_EPS:
            down_steps += 1
    consistency = down_steps / steps if steps > 0 else 0.0
    down = pct <= -min_move and consistency >= min_consistency
    return pct, consistency, down


def _trend_stats_from_series(
    series: Any,
    lookback: int,
    flat_mode: str = "count_as_flat",
    min_span_sec: float = 0.0,
) -> Tuple[Optional[float], Optional[float], Optional[float], bool]:
    # Backward-compatible input: allow callers/tests to pass `List[float]`.
    # In production we usually pass timestamped points to enforce `min_span_sec`.
    if series and isinstance(series, list):
        first = series[0]
        if not isinstance(first, (tuple, list)):
            base = datetime.utcnow()
            coerced: List[Tuple[datetime, float]] = []
            for idx, val in enumerate(series):
                num = to_float(val)
                if num is None or not math.isfinite(num):
                    continue
                coerced.append((base + timedelta(seconds=idx), float(num)))
            series = coerced
    if lookback < 2:
        lookback = 2
    if not series:
        return None, None, None, False
    points = series[-lookback:] if len(series) >= lookback else series[:]
    if len(points) < 2:
        return None, None, None, False
    first_ts, first = points[0]
    last_ts, last = points[-1]
    if first is None or not math.isfinite(first) or first <= 0:
        return None, None, None, False
    if (
        min_span_sec
        and isinstance(first_ts, datetime)
        and isinstance(last_ts, datetime)
        and (last_ts - first_ts).total_seconds() < min_span_sec
    ):
        return None, None, None, False
    pct = last / first - 1.0
    steps = len(points) - 1
    down_steps = 0
    up_steps = 0
    flat_steps = 0
    for idx in range(steps):
        prev = points[idx][1]
        cur = points[idx + 1][1]
        if cur < prev - TIME_EDGE_Q_EPS:
            down_steps += 1
        elif cur > prev + TIME_EDGE_Q_EPS:
            up_steps += 1
        else:
            flat_steps += 1
    if flat_mode == "neutral":
        denom = steps - flat_steps
        if denom <= 0:
            return pct, None, None, True
        down_consistency = down_steps / denom
        up_consistency = up_steps / denom
    else:
        down_consistency = down_steps / steps if steps > 0 else 0.0
        up_consistency = up_steps / steps if steps > 0 else 0.0
    return pct, down_consistency, up_consistency, True


def _model_dir_consensus(
    models: List[str],
    per_model_q: Dict[str, Dict[str, float]],
    history_series: List[Dict[str, float]],
    steps: int,
    ratio: float,
    min_models: int,
    eps: float = TIME_EDGE_Q_EPS,
) -> Tuple[str, float, int, int, int]:
    if steps < 2:
        steps = 2
    total = len(models)
    if total <= 0:
        return "", 0.0, 0, 0, 0
    if len(history_series) < steps:
        return "", 0.0, total, 0, 0
    history_tail = history_series[-steps:]
    current: Dict[str, Optional[float]] = {}
    for model in models:
        try:
            band = per_model_q.get(model, {}) or {}
            dir_value = band.get("dir_value")
            if dir_value is None:
                dir_value = band.get("q_round")
            current[model] = float(dir_value)
        except (TypeError, ValueError):
            current[model] = None
    series = list(history_tail) + [current]
    up = 0
    down = 0
    for model in models:
        values: List[float] = []
        valid = True
        for entry in series:
            val = entry.get(model) if isinstance(entry, dict) else None
            if val is None or not math.isfinite(val):
                valid = False
                break
            values.append(float(val))
        if not valid:
            continue
        dir_up = True
        dir_down = True
        for idx in range(len(values) - 1):
            delta = values[idx + 1] - values[idx]
            if delta <= eps:
                dir_up = False
            if delta >= -eps:
                dir_down = False
        if dir_up:
            up += 1
        elif dir_down:
            down += 1
    ratio_up = up / total if total > 0 else 0.0
    ratio_down = down / total if total > 0 else 0.0
    direction = ""
    consensus_ratio = max(ratio_up, ratio_down)
    if ratio_up >= ratio and up >= min_models and ratio_up > ratio_down:
        direction = "up"
        consensus_ratio = ratio_up
    elif ratio_down >= ratio and down >= min_models and ratio_down > ratio_up:
        direction = "down"
        consensus_ratio = ratio_down
    return direction, consensus_ratio, total, up, down


def _load_entry_state(slug: str, event_date: str) -> Dict[Tuple[str, str], datetime]:
    if not slug or not event_date:
        return {}
    if not DB_PATH.exists():
        return {}
    date_key = event_date.split("T", 1)[0]
    try:
        conn = open_db()
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        try:
            cur.execute(
                """
                SELECT outcome, side, entry_at, last_fill_at, position_size
                FROM edge_trades
                WHERE slug = ? AND event_date = ? AND state = 'entry'
                """,
                (slug, date_key),
            )
            rows = cur.fetchall()
        except sqlite3.OperationalError:
            rows = []
        out: Dict[Tuple[str, str], datetime] = {}
        for row in rows:
            outcome = str(row["outcome"] or "")
            side = str(row["side"] or "")
            if not outcome or not side:
                continue
            pos = to_float(row["position_size"]) if "position_size" in row.keys() else None
            if pos is not None and pos <= 0:
                continue
            entry_at = str(row["entry_at"] or "") if "entry_at" in row.keys() else ""
            if not entry_at:
                entry_at = str(row["last_fill_at"] or "") if "last_fill_at" in row.keys() else ""
            if not entry_at:
                continue
            try:
                ts = datetime.fromisoformat(entry_at)
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=timezone.utc)
            except ValueError:
                continue
            out[(outcome, side)] = ts
        if out:
            return out
        cur.execute(
            """
            SELECT outcome, side, entry_at
            FROM edge_notifications
            WHERE slug = ? AND event_date = ? AND state = 'entry'
            """,
            (slug, date_key),
        )
        rows = cur.fetchall()
    except Exception:
        return {}
    finally:
        try:
            conn.close()
        except Exception:
            pass
    out = {}
    for row in rows:
        outcome = str(row["outcome"] or "")
        side = str(row["side"] or "")
        entry_at = str(row["entry_at"] or "")
        if not outcome or not side or not entry_at:
            continue
        try:
            ts = datetime.fromisoformat(entry_at)
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=timezone.utc)
        except ValueError:
            continue
        out[(outcome, side)] = ts
    return out


