def _lookup_token_from_fills(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
    outcome: str,
    side: str,
) -> str:
    if not slug or not event_date or not outcome or not side:
        return ""
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT token_id
            FROM edge_trade_fills
            WHERE slug = ? AND event_date = ? AND outcome = ? AND outcome_side = ?
              AND token_id IS NOT NULL AND token_id != ''
            ORDER BY trade_time DESC, id DESC
            LIMIT 1
            """,
            (slug, event_date, outcome, side),
        )
        row = cur.fetchone()
    except sqlite3.OperationalError:
        return ""
    if not row:
        return ""
    return str(row[0] or "")


def _latest_tick_for_outcome(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
    outcome: str,
    side: str,
) -> Tuple[
    Optional[float],
    Optional[float],
    Optional[float],
    Optional[float],
    Optional[float],
    Optional[float],
    Optional[float],
    Optional[float],
]:
    if not slug or not event_date or not outcome or not side:
        return None, None, None, None, None, None, None, None
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT best_bid, best_ask, bid_depth_topN, ask_depth_topN
            FROM event_market_ticks
            WHERE slug = ? AND event_date = ? AND outcome = ? AND side = ?
            ORDER BY created_at DESC, id DESC
            LIMIT 2
            """,
            (slug, event_date, outcome, side),
        )
        rows = cur.fetchall()
    except sqlite3.OperationalError:
        return None, None, None, None, None, None, None, None
    if not rows:
        return None, None, None, None, None, None, None, None
    best_bid = to_float(rows[0][0]) if rows[0][0] is not None else None
    best_ask = to_float(rows[0][1]) if rows[0][1] is not None else None
    bid_depth = to_float(rows[0][2]) if rows[0][2] is not None else None
    ask_depth = to_float(rows[0][3]) if rows[0][3] is not None else None
    if len(rows) > 1:
        prev_bid = to_float(rows[1][0]) if rows[1][0] is not None else None
        prev_ask = to_float(rows[1][1]) if rows[1][1] is not None else None
        prev_bid_depth = to_float(rows[1][2]) if rows[1][2] is not None else None
        prev_ask_depth = to_float(rows[1][3]) if rows[1][3] is not None else None
    else:
        prev_bid = best_bid
        prev_ask = best_ask
        prev_bid_depth = bid_depth
        prev_ask_depth = ask_depth
    return best_bid, best_ask, bid_depth, ask_depth, prev_bid, prev_ask, prev_bid_depth, prev_ask_depth


def _augment_rows_with_positions(
    rows: List[Dict[str, Any]],
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
) -> List[Dict[str, Any]]:
    if not rows:
        rows = []
    if not slug or not event_date:
        return rows
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT outcome, side
            FROM edge_trades
            WHERE slug = ? AND event_date = ?
              AND position_size IS NOT NULL AND position_size > 0
            """,
            (slug, event_date),
        )
        open_rows = cur.fetchall()
    except sqlite3.OperationalError:
        return rows
    if not open_rows:
        return rows
    outcome_map: Dict[str, Dict[str, Any]] = {}
    for row in rows:
        outcome = str(row.get("outcome") or "")
        if outcome and outcome not in outcome_map:
            outcome_map[outcome] = row
    for open_row in open_rows:
        outcome = str(open_row[0] or "")
        side = str(open_row[1] or "").upper()
        if not outcome or side not in {"YES", "NO"}:
            continue
        row = outcome_map.get(outcome)
        if row is None:
            row = {"outcome": outcome, "synthetic_exit_only": True}
            rows.append(row)
            outcome_map[outcome] = row
            print(f"[auto-trade] add exit row {slug} {outcome} side={side} reason=missing_bucket")
        token_key = "yes_token" if side == "YES" else "no_token"
        if not row.get(token_key):
            token_id = _lookup_token_from_fills(conn, slug, event_date, outcome, side)
            if token_id:
                row[token_key] = token_id
        bid_key = "best_bid" if side == "YES" else "best_bid_no"
        ask_key = "best_ask" if side == "YES" else "best_ask_no"
        prev_bid_key = "prev_best_bid" if side == "YES" else "prev_best_bid_no"
        prev_ask_key = "prev_best_ask" if side == "YES" else "prev_best_ask_no"
        if row.get(bid_key) is None and row.get(ask_key) is None:
            (
                best_bid,
                best_ask,
                bid_depth,
                ask_depth,
                prev_bid,
                prev_ask,
                _prev_bid_depth,
                _prev_ask_depth,
            ) = _latest_tick_for_outcome(conn, slug, event_date, outcome, side)
            if best_bid is not None:
                row[bid_key] = best_bid
            if best_ask is not None:
                row[ask_key] = best_ask
            depth_bid_key = "bid_depth_topN" if side == "YES" else "bid_depth_topN_no"
            depth_ask_key = "ask_depth_topN" if side == "YES" else "ask_depth_topN_no"
            if row.get(depth_bid_key) is None and bid_depth is not None:
                row[depth_bid_key] = bid_depth
            if row.get(depth_ask_key) is None and ask_depth is not None:
                row[depth_ask_key] = ask_depth
            if prev_bid is not None:
                row[prev_bid_key] = prev_bid
            if prev_ask is not None:
                row[prev_ask_key] = prev_ask
            if side == "YES":
                if row.get("spread") is None and best_bid is not None and best_ask is not None:
                    row["spread"] = max(best_ask - best_bid, 0.0)
            else:
                if row.get("spread_no") is None and best_bid is not None and best_ask is not None:
                    row["spread_no"] = max(best_ask - best_bid, 0.0)
        if row.get(prev_bid_key) is None and row.get(bid_key) is not None:
            row[prev_bid_key] = row.get(bid_key)
        if row.get(prev_ask_key) is None and row.get(ask_key) is not None:
            row[prev_ask_key] = row.get(ask_key)
    return rows


def _fill_rows_with_latest_ticks(
    rows: List[Dict[str, Any]],
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
) -> None:
    if not rows or not slug or not event_date:
        return
    for row in rows:
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        (
            best_bid,
            best_ask,
            bid_depth,
            ask_depth,
            _prev_bid,
            _prev_ask,
            _prev_bid_depth,
            _prev_ask_depth,
        ) = _latest_tick_for_outcome(conn, slug, event_date, outcome, "YES")
        if row.get("best_bid") is None and best_bid is not None:
            row["best_bid"] = best_bid
        if row.get("best_ask") is None and best_ask is not None:
            row["best_ask"] = best_ask
        if row.get("spread") is None and best_bid is not None and best_ask is not None:
            row["spread"] = max(best_ask - best_bid, 0.0)
        if row.get("bid_depth_topN") is None and bid_depth is not None:
            row["bid_depth_topN"] = bid_depth
        if row.get("ask_depth_topN") is None and ask_depth is not None:
            row["ask_depth_topN"] = ask_depth

        (
            best_bid_no,
            best_ask_no,
            bid_depth_no,
            ask_depth_no,
            _prev_bid_no,
            _prev_ask_no,
            _prev_bid_depth_no,
            _prev_ask_depth_no,
        ) = _latest_tick_for_outcome(conn, slug, event_date, outcome, "NO")
        if row.get("best_bid_no") is None and best_bid_no is not None:
            row["best_bid_no"] = best_bid_no
        if row.get("best_ask_no") is None and best_ask_no is not None:
            row["best_ask_no"] = best_ask_no
        if row.get("spread_no") is None and best_bid_no is not None and best_ask_no is not None:
            row["spread_no"] = max(best_ask_no - best_bid_no, 0.0)
        if row.get("bid_depth_topN_no") is None and bid_depth_no is not None:
            row["bid_depth_topN_no"] = bid_depth_no
        if row.get("ask_depth_topN_no") is None and ask_depth_no is not None:
            row["ask_depth_topN_no"] = ask_depth_no


def _edge_level(headroom: Optional[float]) -> Tuple[str, float]:
    if headroom is None:
        return "", 0.0
    h_pct = headroom * 100.0
    for low, high, label, ratio in EDGE_LEVELS:
        if h_pct >= low and h_pct < high:
            return label, ratio
    return "", 0.0


def _ask_discount(ask: Optional[float]) -> float:
    if ask is None:
        return 1.0
    try:
        pct = float(ask) * 100.0
    except (TypeError, ValueError):
        return 1.0
    if pct > 90.0:
        return 0.5
    if pct > 80.0:
        return 0.7
    return 1.0


def _is_tail_locked_quote(ask: Optional[float], q_prob: Optional[float]) -> bool:
    if not MINUTE_EDGE_ENTRY_TAIL_LOCK_ENABLED:
        return False
    if ask is None or not math.isfinite(ask):
        return False
    if ask <= MINUTE_EDGE_ENTRY_TAIL_LOCK_ASK_HARD + TIME_EDGE_Q_EPS:
        return True
    if q_prob is None or not math.isfinite(q_prob):
        return False
    return (
        ask <= MINUTE_EDGE_ENTRY_TAIL_LOCK_ASK_SOFT + TIME_EDGE_Q_EPS
        and q_prob >= MINUTE_EDGE_ENTRY_TAIL_LOCK_Q_MIN - TIME_EDGE_Q_EPS
    )


def _format_pct(value: Optional[float], decimals: int = 1) -> str:
    if value is None:
        return "—"
    try:
        return f"{value * 100:.{decimals}f}%"
    except (TypeError, ValueError):
        return "—"


def _format_ratio(value: Optional[float], decimals: int = 2) -> str:
    if value is None:
        return "—"
    try:
        return f"{value:.{decimals}f}"
    except (TypeError, ValueError):
        return "—"


def _entry_depth_mult(
    edge_score: Optional[float],
    min_mult: float,
    max_mult: float,
    slope: float,
) -> float:
    if max_mult <= 0:
        return 0.0
    if edge_score is None or not math.isfinite(edge_score):
        return max_mult
    if min_mult > max_mult:
        min_mult = max_mult
    mult = max_mult - slope * edge_score
    return max(min_mult, min(max_mult, mult))


def _format_usdc(value: Optional[float]) -> str:
    if value is None:
        return "—"
    try:
        return f"${value:.2f}"
    except (TypeError, ValueError):
        return "—"


def _env_float(key: str, default: Optional[float] = None) -> Optional[float]:
    val = to_float(os.environ.get(key))
    if val is None or not math.isfinite(val):
        return float(default) if default is not None else None
    return float(val)


def _env_int(key: str) -> Optional[int]:
    raw = os.environ.get(key)
    if raw is None:
        return None
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None


def _sqlite_locked_error(exc: Exception) -> bool:
    text = str(exc or "").lower()
    return "locked" in text or "busy" in text


def _sqlite_execute_with_retry(
    cur: sqlite3.Cursor,
    sql: str,
    params: Tuple[Any, ...] = (),
    *,
    attempts: int = 8,
    sleep_base_sec: float = 0.25,
    sleep_cap_sec: float = 2.0,
) -> None:
    max_attempts = max(1, int(attempts))
    base_sleep = max(0.0, float(sleep_base_sec))
    cap_sleep = max(0.0, float(sleep_cap_sec))
    for attempt in range(max_attempts):
        try:
            cur.execute(sql, params)
            return
        except sqlite3.OperationalError as exc:
            if (not _sqlite_locked_error(exc)) or attempt >= (max_attempts - 1):
                raise
            if base_sleep <= 0:
                continue
            sleep_for = base_sleep * float(attempt + 1)
            if cap_sleep > 0:
                sleep_for = min(sleep_for, cap_sleep)
            time.sleep(sleep_for)


def _sqlite_executemany_with_retry(
    cur: sqlite3.Cursor,
    sql: str,
    seq_of_params: Iterable[Tuple[Any, ...]],
    *,
    attempts: int = 8,
    sleep_base_sec: float = 0.25,
    sleep_cap_sec: float = 2.0,
) -> None:
    max_attempts = max(1, int(attempts))
    base_sleep = max(0.0, float(sleep_base_sec))
    cap_sleep = max(0.0, float(sleep_cap_sec))
    for attempt in range(max_attempts):
        try:
            cur.executemany(sql, seq_of_params)
            return
        except sqlite3.OperationalError as exc:
            if (not _sqlite_locked_error(exc)) or attempt >= (max_attempts - 1):
                raise
            if base_sleep <= 0:
                continue
            sleep_for = base_sleep * float(attempt + 1)
            if cap_sleep > 0:
                sleep_for = min(sleep_for, cap_sleep)
            time.sleep(sleep_for)


def _facts_lock_wait_sec(default: float = 45.0) -> float:
    val = _env_float("PM_FACTS_LOCK_WAIT_SEC", default)
    if val is None or not math.isfinite(val) or val < 0:
        return float(default)
    return float(val)


def _facts_lock_poll_sec(default: float = 1.0) -> float:
    val = _env_float("PM_FACTS_LOCK_POLL_SEC", default)
    if val is None or not math.isfinite(val) or val <= 0:
        return float(default)
    return max(0.2, min(float(val), 10.0))


def _facts_lock_active() -> bool:
    try:
        return FACTS_MATERIALIZE_LOCK_DIR.exists()
    except OSError:
        return False


def _db_writer_lock_active() -> bool:
    try:
        return DB_WRITER_LOCK_DIR.exists()
    except OSError:
        return False


def _db_writer_lock_wait_sec(default: float = 10.0) -> float:
    val = _env_float("PM_DB_WRITER_LOCK_WAIT_SEC", default)
    if val is None or not math.isfinite(val) or val < 0:
        return float(default)
    return float(val)


def _wait_for_db_writer_lock(tag: str, wait_sec: Optional[float] = None) -> bool:
    max_wait = _db_writer_lock_wait_sec() if wait_sec is None else float(wait_sec)
    if not math.isfinite(max_wait) or max_wait <= 0:
        return True
    poll = _facts_lock_poll_sec()
    waited = 0.0
    while _db_writer_lock_active():
        if waited >= max_wait:
            print(f"[{tag}] db_writer lock active, skip (waited={int(waited)}s)")
            return False
        sleep_for = min(poll, max_wait - waited)
        if sleep_for <= 0:
            break
        time.sleep(sleep_for)
        waited += sleep_for
    if waited > 0:
        print(f"[{tag}] db_writer lock cleared after {int(waited)}s")
    return True


def _wait_for_facts_lock(tag: str, wait_sec: Optional[float] = None) -> bool:
    max_wait = _facts_lock_wait_sec() if wait_sec is None else float(wait_sec)
    if not math.isfinite(max_wait) or max_wait <= 0:
        return True
    poll = _facts_lock_poll_sec()
    waited = 0.0
    while _facts_lock_active():
        if waited >= max_wait:
            print(f"[{tag}] facts lock active, skip (waited={int(waited)}s)")
            return False
        sleep_for = min(poll, max_wait - waited)
        if sleep_for <= 0:
            break
        time.sleep(sleep_for)
        waited += sleep_for
    if waited > 0:
        print(f"[{tag}] facts lock cleared after {int(waited)}s")
    return True


def _resolve_order_size(
    price: Optional[float],
    position_ratio: Optional[float],
    notional_override: Optional[float] = None,
) -> Optional[float]:
    if price is None or price <= 0:
        return None
    ratio = float(position_ratio) if position_ratio is not None else 0.0
    bankroll = _env_float("PM_BANKROLL_USDC")
    notional = None
    if bankroll is not None and ratio > 0:
        notional = bankroll * ratio
    elif notional_override is not None and math.isfinite(notional_override) and notional_override > 0:
        notional = notional_override
    else:
        notional = _env_float("PM_ORDER_USDC")
    if notional is not None:
        size = notional / float(price)
    else:
        size = _env_float("PM_ORDER_SIZE")
    if size is None:
        return None
    max_notional = _env_float("PM_MAX_ORDER_USDC")
    if max_notional is not None and max_notional > 0:
        size_cap = max_notional / float(price)
        if size_cap > 0:
            size = min(size, size_cap)
    max_size = _env_float("PM_MAX_ORDER_SIZE")
    if max_size is not None and max_size > 0 and size > max_size:
        size = max_size
    min_size = _env_float("PM_MIN_ORDER_SIZE") or 0.0
    if min_size > 0 and size < min_size:
        size = min_size
    return round(size, 4)


def _clamp_prob01(value: Optional[float]) -> Optional[float]:
    if value is None or not math.isfinite(value):
        return None
    return max(0.0, min(1.0, float(value)))


def _candidate_entry_prob(candidate: Dict[str, Any], price: float) -> Optional[float]:
    for key in ("q_entry", "q_prob", "q_calibrated", "q_raw"):
        val = to_float(candidate.get(key))
        val = _clamp_prob01(val)
        if val is not None:
            return val
    ask_val = to_float(candidate.get("ask"))
    edge_min = to_float(candidate.get("edge_min"))
    if edge_min is not None and math.isfinite(edge_min):
        if ask_val is not None and math.isfinite(ask_val):
            val = _clamp_prob01(float(ask_val) + float(edge_min))
            if val is not None:
                return val
        val = _clamp_prob01(float(price) + float(edge_min))
        if val is not None:
            return val
    return None


def _apply_kelly_size_in_place(
    candidate: Dict[str, Any],
    *,
    allow_apply: bool,
) -> None:
    if not isinstance(candidate, dict):
        return
    candidate["kelly_enabled"] = bool(_env_bool("PM_KELLY_ENABLED", True))
    candidate["kelly_applied"] = False
    candidate["kelly_blocked"] = False
    candidate["kelly_reason"] = ""

    enabled = bool(candidate.get("kelly_enabled"))
    if not enabled:
        candidate["kelly_reason"] = "kelly_disabled"
        return
    if not allow_apply:
        candidate["kelly_reason"] = "topup_skip"
        return

    price = to_float(candidate.get("price") or candidate.get("order_price"))
    if price is None or not math.isfinite(price) or price <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "price_invalid"
        return
    price = max(TIME_EDGE_Q_EPS, min(float(price), 1.0 - TIME_EDGE_Q_EPS))
    candidate["kelly_price"] = float(price)

    size_before = to_float(candidate.get("size"))
    base_notional = None
    if (
        size_before is not None
        and math.isfinite(size_before)
        and size_before > TIME_EDGE_Q_EPS
    ):
        base_notional = float(size_before) * float(price)
    if base_notional is None:
        fallback_notional = _env_float("PM_ORDER_USDC")
        if (
            fallback_notional is not None
            and math.isfinite(fallback_notional)
            and fallback_notional > TIME_EDGE_Q_EPS
        ):
            base_notional = float(fallback_notional)
    if base_notional is None or base_notional <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "base_notional_missing"
        return
    candidate["kelly_base_notional"] = float(base_notional)
    if size_before is not None and math.isfinite(size_before):
        candidate["kelly_size_before"] = float(size_before)

    q_prob = _candidate_entry_prob(candidate, float(price))
    if q_prob is None:
        candidate["kelly_reason"] = "q_missing"
        return
    q_prob = max(TIME_EDGE_Q_EPS, min(float(q_prob), 1.0 - TIME_EDGE_Q_EPS))
    candidate["kelly_q_prob"] = float(q_prob)

    # Binary contract Kelly fraction (buy side):
    # f* = (q - p) / (1 - p), then use fractional Kelly and confidence damping.
    kelly_raw = (float(q_prob) - float(price)) / max(1.0 - float(price), TIME_EDGE_Q_EPS)
    candidate["kelly_fraction_raw"] = float(kelly_raw)
    if not math.isfinite(kelly_raw) or kelly_raw <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "kelly_nonpositive"
        if _env_bool("PM_KELLY_BLOCK_NONPOSITIVE", False):
            candidate["kelly_blocked"] = True
        return

    kelly_fraction = _env_float("PM_KELLY_FRACTION")
    if kelly_fraction is None or not math.isfinite(kelly_fraction) or kelly_fraction <= 0:
        kelly_fraction = 0.25
    kelly_fraction = max(0.0, min(1.0, float(kelly_fraction)))
    candidate["kelly_fraction_cfg"] = float(kelly_fraction)

    prob_components: List[float] = []
    for key in ("edge_realizable_p_realize", "edge_path_p_reach_lcb", "edge_realizable_p_converge"):
        v = _clamp_prob01(to_float(candidate.get(key)))
        if v is not None:
            prob_components.append(float(v))
    quality_anchor = min(prob_components) if prob_components else 1.0
    quality_mult = 0.5 + 0.5 * float(quality_anchor)
    quality_mult = max(0.0, min(1.0, quality_mult))
    candidate["kelly_quality_anchor"] = float(quality_anchor)
    candidate["kelly_quality_mult"] = float(quality_mult)

    kelly_effective = float(kelly_raw) * float(kelly_fraction) * float(quality_mult)
    candidate["kelly_fraction_effective"] = float(kelly_effective)
    if kelly_effective <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "kelly_effective_nonpositive"
        if _env_bool("PM_KELLY_BLOCK_NONPOSITIVE", False):
            candidate["kelly_blocked"] = True
        return

    bankroll = _env_float("PM_BANKROLL_USDC")
    target_notional = None
    sizing_source = "base_scaled"
    if bankroll is not None and math.isfinite(bankroll) and bankroll > TIME_EDGE_Q_EPS:
        target_notional = float(bankroll) * float(kelly_effective)
        sizing_source = "bankroll_fraction"
    if target_notional is None:
        ref_fraction = _env_float("PM_KELLY_REF_FRACTION")
        if ref_fraction is None or not math.isfinite(ref_fraction) or ref_fraction <= 0:
            ref_fraction = 0.05
        ref_fraction = max(float(ref_fraction), TIME_EDGE_Q_EPS)
        candidate["kelly_ref_fraction"] = float(ref_fraction)
        scale = float(kelly_effective) / float(ref_fraction)
        min_scale = _env_float("PM_KELLY_MIN_SCALE")
        max_scale = _env_float("PM_KELLY_MAX_SCALE")
        if min_scale is None or not math.isfinite(min_scale) or min_scale < 0:
            min_scale = 0.5
        if max_scale is None or not math.isfinite(max_scale) or max_scale <= 0:
            max_scale = 2.0
        if max_scale < min_scale:
            max_scale = min_scale
        scale = max(float(min_scale), min(float(max_scale), float(scale)))
        candidate["kelly_scale"] = float(scale)
        target_notional = float(base_notional) * float(scale)

    min_notional = _env_float("PM_KELLY_MIN_NOTIONAL_USDC")
    if min_notional is not None and (not math.isfinite(min_notional) or min_notional < 0):
        min_notional = None
    max_notional = _env_float("PM_KELLY_MAX_NOTIONAL_USDC")
    if max_notional is not None and (not math.isfinite(max_notional) or max_notional <= 0):
        max_notional = None
    hard_cap_notional = _env_float("PM_MAX_ORDER_USDC")
    if hard_cap_notional is not None and (not math.isfinite(hard_cap_notional) or hard_cap_notional <= 0):
        hard_cap_notional = None
    if hard_cap_notional is not None:
        max_notional = min(max_notional, hard_cap_notional) if max_notional is not None else hard_cap_notional
    if min_notional is not None:
        target_notional = max(float(target_notional), float(min_notional))
    if max_notional is not None:
        target_notional = min(float(target_notional), float(max_notional))
    if target_notional <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "target_notional_nonpositive"
        if _env_bool("PM_KELLY_BLOCK_NONPOSITIVE", False):
            candidate["kelly_blocked"] = True
        return
    candidate["kelly_target_notional"] = float(target_notional)
    candidate["kelly_sizing_source"] = str(sizing_source)

    size_new = float(target_notional) / float(price)
    min_size = _env_float("PM_MIN_ORDER_SIZE")
    if min_size is not None and math.isfinite(min_size) and min_size > 0:
        size_new = max(float(size_new), float(min_size))
    max_size = _env_float("PM_MAX_ORDER_SIZE")
    if max_size is not None and math.isfinite(max_size) and max_size > 0:
        size_new = min(float(size_new), float(max_size))
    if not math.isfinite(size_new) or size_new <= TIME_EDGE_Q_EPS:
        candidate["kelly_reason"] = "size_after_kelly_invalid"
        if _env_bool("PM_KELLY_BLOCK_NONPOSITIVE", False):
            candidate["kelly_blocked"] = True
        return

    candidate["size"] = round(float(size_new), 4)
    candidate["kelly_applied"] = True
    candidate["kelly_reason"] = "applied"


def _normalize_nonnegative_ratio(value: Optional[float], default: float = 1.0) -> float:
    ratio = to_float(value)
    if ratio is None or not math.isfinite(ratio):
        ratio = default
    ratio = float(ratio)
    if ratio < 0:
        ratio = 0.0
    return ratio


def _parse_order_usdc_tiers(raw: Optional[str]) -> List[Dict[str, float]]:
    if not raw:
        return []
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        return []
    if not isinstance(payload, list):
        return []
    tiers: List[Dict[str, float]] = []
    for item in payload:
        if not isinstance(item, dict):
            continue
        order_usdc = to_float(item.get("order_usdc"))
        if order_usdc is None or not math.isfinite(order_usdc) or order_usdc <= 0:
            continue
        min_edge_score = to_float(item.get("min_edge_score"))
        min_edge_conf = to_float(item.get("min_edge_confidence"))
        tiers.append(
            {
                "order_usdc": float(order_usdc),
                "min_edge_score": min_edge_score,
                "min_edge_confidence": min_edge_conf,
            }
        )
    tiers.sort(key=lambda t: float(t.get("order_usdc") or 0.0))
    return tiers


def _resolve_order_usdc_tier(
    edge_score: Optional[float],
    edge_confidence: Optional[float],
    tiers: List[Dict[str, float]],
) -> Optional[float]:
    if not tiers:
        return None
    if edge_score is None or not math.isfinite(edge_score):
        return None
    best: Optional[float] = None
    for tier in tiers:
        min_score = to_float(tier.get("min_edge_score"))
        min_conf = to_float(tier.get("min_edge_confidence"))
        if min_score is not None and math.isfinite(min_score):
            if edge_score + TIME_EDGE_Q_EPS < min_score:
                continue
        if min_conf is not None and math.isfinite(min_conf):
            if edge_confidence is None or not math.isfinite(edge_confidence):
                if min_conf > 0:
                    continue
            elif edge_confidence + TIME_EDGE_Q_EPS < min_conf:
                continue
        order_usdc = to_float(tier.get("order_usdc"))
        if order_usdc is None or not math.isfinite(order_usdc) or order_usdc <= 0:
            continue
        if best is None or order_usdc > best + TIME_EDGE_Q_EPS:
            best = float(order_usdc)
    return best


def _model_cache_key(lat: float, lon: float) -> str:
    return f"{lat:.4f},{lon:.4f}"


def _model_cache_ttl_sec(model: str) -> int:
    if model == "nws_forecast":
        return _env_int("PM_CACHE_TTL_NWS_SEC") or 3600
    return _env_int("PM_CACHE_TTL_ENSEMBLE_SEC") or 21600


def _model_window_minutes() -> int:
    return _env_int("PM_MODEL_WINDOW_MINUTES") or 180


def _model_background_refresh_minutes() -> int:
    return _env_int("PM_MODEL_BACKGROUND_REFRESH_MINUTES") or 45


def _model_window_refresh_minutes() -> int:
    return _env_int("PM_MODEL_WINDOW_REFRESH_MINUTES") or 3


def _model_cache_max_age_sec() -> int:
    return _env_int("PM_MODEL_CACHE_MAX_AGE_SEC") or 172800


def _event_days_out(event_date: str, now: datetime) -> Optional[int]:
    if not event_date:
        return None
    try:
        ev_date = datetime.fromisoformat(event_date).date()
    except Exception:
        return None
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    return (ev_date - now.date()).days


def _model_refresh_minutes_for_event(event_date: str, now: datetime) -> Tuple[int, int]:
    default_min = _env_int("PM_MODEL_REFRESH_MINUTES_DEFAULT") or _model_background_refresh_minutes()
    d0d1_min = _env_int("PM_MODEL_REFRESH_MINUTES_D0D1") or 10
    d3_min = _env_int("PM_MODEL_REFRESH_MINUTES_D3PLUS") or 60
    days_out = _event_days_out(event_date, now)
    if days_out is None:
        return default_min, default_min
    if days_out <= 1:
        return d0d1_min, d0d1_min
    if days_out >= 3:
        return d3_min, d3_min
    return default_min, default_min


def _parse_cycle_hours(raw: Optional[str]) -> Optional[List[int]]:
    if not raw:
        return None
    try:
        offsets = [int(x.strip()) for x in raw.split(",") if x.strip()]
    except ValueError:
        return None
    return offsets or None


def _model_cycle_hours(model: str) -> Optional[List[int]]:
    if not model:
        return None
    env_key = f"PM_MODEL_CYCLE_HOURS_{model.upper()}"
    offsets = _parse_cycle_hours(os.environ.get(env_key))
    if offsets:
        return offsets
    offsets = _parse_cycle_hours(os.environ.get("PM_ENSEMBLE_CYCLE_HOURS"))
    if offsets:
        return offsets
    return MODEL_CYCLE_DEFAULTS.get(model)


def _estimate_model_run_at(model: str, base_time: datetime) -> Optional[datetime]:
    offsets = _model_cycle_hours(model)
    if not offsets:
        return None
    if base_time.tzinfo is None:
        base_time = base_time.replace(tzinfo=timezone.utc)
    delay_hours = _env_int("PM_ENSEMBLE_CYCLE_DELAY_HOURS") or 2
    anchor = _aligned_model_refresh_ts(base_time - timedelta(hours=delay_hours), offsets, 0)
    return anchor


def _is_within_model_window(model: str, now: datetime) -> bool:
    offsets = _model_cycle_hours(model)
    if not offsets:
        return True
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    delay_hours = _env_int("PM_ENSEMBLE_CYCLE_DELAY_HOURS") or 2
    window_minutes = _model_window_minutes()
    for back_days in range(0, 2):
        base = (now - timedelta(days=back_days)).replace(
            hour=0, minute=0, second=0, microsecond=0
        )
        for hour in offsets:
            start = base + timedelta(hours=hour + delay_hours)
            end = start + timedelta(minutes=window_minutes)
            if start <= now <= end:
                return True
    return False


def _should_fetch_model_now(
    model: str,
    loc_key: str,
    date: str,
    market_var: str,
    market_unit: str,
    now: datetime,
) -> Tuple[bool, str]:
    if model == "nws_forecast":
        return True, "nws"
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    meta = _load_latest_model_cache_meta(model, loc_key, date, market_var, market_unit)
    last_update = ""
    created_at_raw = ""
    if meta:
        last_update = meta.get("official_updated_at") or meta.get("created_at") or ""
        created_at_raw = meta.get("created_at") or ""
    if not last_update:
        return True, "no_cache"
    last_dt = _parse_iso_dt(last_update)
    if last_dt is None:
        return True, "no_cache"
    if last_dt.tzinfo is None:
        last_dt = last_dt.replace(tzinfo=timezone.utc)
    age_min = (now - last_dt).total_seconds() / 60.0
    window_min, background_min = _model_refresh_minutes_for_event(date, now)
    strict_cycle = _env_bool("PM_MODEL_STRICT_CYCLE", False)
    if strict_cycle:
        created_at_dt = _parse_iso_dt(created_at_raw)
        if created_at_dt is None:
            created_at_dt = last_dt
        if _is_within_model_window(model, now):
            if _model_cache_force_refresh(model, created_at_dt, now):
                return True, "cycle_window"
            return False, "cycle_hold"
        return False, "cycle_wait"
    if _is_within_model_window(model, now):
        if age_min >= window_min:
            return True, "window"
        return False, "window_hold"
    if age_min >= background_min:
        return True, "background"
    return False, "throttle"


def _aligned_model_refresh_ts(
    now: datetime,
    offsets: Optional[List[int]],
    delay_hours: int,
) -> Optional[datetime]:
    if not offsets:
        return None
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    for back_days in range(0, 3):
        base = (now - timedelta(days=back_days)).replace(
            hour=0, minute=0, second=0, microsecond=0
        )
        for hour in sorted(offsets, reverse=True):
            candidate = base + timedelta(hours=hour + delay_hours)
            if candidate <= now:
                return candidate
    return None


def _model_cache_force_refresh(
    model: str,
    created_at: Optional[datetime],
    now: datetime,
) -> bool:
    if created_at is None:
        return True
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    created_at = created_at if created_at.tzinfo else created_at.replace(tzinfo=timezone.utc)
    if model == "nws_forecast":
        return False
    offsets = _model_cycle_hours(model)
    if not offsets:
        return False
    delay_hours = _env_int("PM_ENSEMBLE_CYCLE_DELAY_HOURS") or 2
    anchor = _aligned_model_refresh_ts(now, offsets, delay_hours)
    if anchor is None:
        return False
    return created_at < anchor


def _sleep_open_meteo_spacing() -> None:
    if OPEN_METEO_GLOBAL_RATE_LIMIT:
        return
    low = max(0.0, OPEN_METEO_MODEL_SPACING_MIN)
    high = max(low, OPEN_METEO_MODEL_SPACING_MAX)
    if high <= 0:
        return
    time.sleep(random.uniform(low, high))


def _open_meteo_global_spacing_sec() -> float:
    low = max(0.0, OPEN_METEO_MODEL_SPACING_MIN)
    high = max(low, OPEN_METEO_MODEL_SPACING_MAX)
    if high <= 0:
        return 0.0
    return float(random.uniform(low, high))


def _open_meteo_wait_global_slot(scope: str = "open_meteo") -> float:
    if not OPEN_METEO_GLOBAL_RATE_LIMIT:
        return 0.0
    delay = _open_meteo_global_spacing_sec()
    if delay <= 0 or not DB_PATH.exists():
        return 0.0
    key = f"net_rate:{scope}"
    wait_sec = 0.0
    conn = None
    try:
        conn = open_db()
        cur = conn.cursor()
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS net_rate_limits (
                key TEXT PRIMARY KEY,
                next_allowed_at TEXT,
                updated_at TEXT
            )
            """
        )
        conn.commit()
        for _ in range(6):
            try:
                conn.execute("BEGIN IMMEDIATE")
                cur = conn.cursor()
                cur.execute(
                    "SELECT next_allowed_at FROM net_rate_limits WHERE key = ?",
                    (key,),
                )
                row = cur.fetchone()
                next_allowed = _parse_iso_dt(str(row[0] or "")) if row else None
                now = datetime.now(timezone.utc)
                if next_allowed is not None and next_allowed.tzinfo is None:
                    next_allowed = next_allowed.replace(tzinfo=timezone.utc)
                if next_allowed is not None and next_allowed > now:
                    wait_sec = (next_allowed - now).total_seconds()
                else:
                    wait_sec = 0.0
                reserved_at = now + timedelta(seconds=max(0.0, wait_sec))
                next_dt = reserved_at + timedelta(seconds=float(delay))
                cur.execute(
                    """
                    INSERT INTO net_rate_limits(key, next_allowed_at, updated_at)
                    VALUES (?, ?, ?)
                    ON CONFLICT(key) DO UPDATE SET
                      next_allowed_at = excluded.next_allowed_at,
                      updated_at = excluded.updated_at
                    """,
                    (key, next_dt.isoformat(), now.isoformat()),
                )
                conn.commit()
                break
            except sqlite3.OperationalError:
                try:
                    conn.rollback()
                except Exception:
                    pass
                time.sleep(0.05 + random.uniform(0.0, 0.2))
                continue
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass
    if wait_sec > 0:
        time.sleep(wait_sec)
    return float(wait_sec)


def _clob_book_global_spacing_sec() -> float:
    low = max(0.0, CLOB_BOOK_SPACING_MIN)
