    edge_realizable_v2_enabled = _env_bool("PM_EDGE_REALIZABLE_V2_ENABLED", False)
    edge_realizable_v2_gate_entry = _env_bool("PM_EDGE_REALIZABLE_V2_GATE_ENTRY", edge_realizable_v2_enabled)
