    def _strategy_entry_size_ratio(strategy_name: str) -> float:
        key = str(strategy_name or "").strip().lower() or "main"
        return _normalize_nonnegative_ratio(entry_size_ratio_by_strategy.get(key), 1.0)

    def _apply_strategy_size_ratio_in_place(candidate_ref: Dict[str, Any]) -> Tuple[Optional[float], float, Optional[float]]:
        if not isinstance(candidate_ref, dict):
            return None, 1.0, None
        if candidate_ref.get("_strategy_size_ratio_applied"):
            ratio_existing = _normalize_nonnegative_ratio(
                to_float(candidate_ref.get("strategy_size_ratio")),
                1.0,
            )
            size_existing = to_float(candidate_ref.get("size"))
            size_base_existing = to_float(candidate_ref.get("size_base"))
            return size_existing, ratio_existing, size_base_existing
        strategy_name = str(candidate_ref.get("strategy") or "main").strip().lower()
        ratio_val = _strategy_entry_size_ratio(strategy_name)
        size_base = to_float(candidate_ref.get("size"))
        candidate_ref["strategy_size_ratio"] = ratio_val
        candidate_ref["size_base"] = size_base
        candidate_ref["_strategy_size_ratio_applied"] = True
        if size_base is None or not math.isfinite(size_base):
            candidate_ref["size_scaled"] = None
            candidate_ref["size"] = None
            return None, ratio_val, size_base
        scaled = round(max(float(size_base) * float(ratio_val), 0.0), 4)
        candidate_ref["size_scaled"] = scaled
        candidate_ref["size"] = scaled
        return scaled, ratio_val, size_base
