def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _normalize_date_key(value: str) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if "T" in text:
        return text.split("T", 1)[0]
    if " " in text:
        return text.split(" ", 1)[0]
    return text


def to_jsonable_result(result: Dict) -> Dict:
    out = dict(result)
    out["members"] = [float(x) for x in result["members"]]
    model_members = result.get("model_members")
    if isinstance(model_members, dict):
        out["model_members"] = {
            k: [float(x) for x in v] for k, v in model_members.items()
        }
    out["rows"] = [dict(r) for r in result["rows"]]
    return out


def _to_finite_float(value: Any) -> Optional[float]:
    parsed = to_float(value)
    if parsed is None or not math.isfinite(parsed):
        return None
    return parsed


def _load_latest_payload_rows(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
) -> List[Dict[str, Any]]:
    if not slug or not event_date:
        return []
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT payload_json
            FROM event_runs
            WHERE slug = ? AND event_date = ?
            ORDER BY created_at DESC, id DESC
            LIMIT 1
            """,
            (slug, event_date),
        )
        row = cur.fetchone()
    except sqlite3.Error:
        return []
    if not row:
        return []
    payload_raw = row[0] if isinstance(row, tuple) else row["payload_json"]
    if not payload_raw:
        return []
    try:
        payload = json.loads(payload_raw)
    except (TypeError, json.JSONDecodeError):
        return []
    rows = payload.get("rows")
    if not isinstance(rows, list):
        return []
    merged_rows: List[Dict[str, Any]] = []
    for item in rows:
        if isinstance(item, Mapping):
            merged_rows.append(dict(item))
    return merged_rows


def _merge_rows_preserve_edge_scores(
    current_rows: List[Dict[str, Any]],
    previous_rows: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    if not current_rows or not previous_rows:
        return current_rows

    previous_lookup: Dict[str, Dict[str, Any]] = {}
    for row in previous_rows:
        if not isinstance(row, Mapping):
            continue
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        row_copy = dict(row)
        previous_lookup[outcome] = row_copy
        normalized = _normalize_outcome_key(outcome)
        if normalized and normalized not in previous_lookup:
            previous_lookup[normalized] = row_copy

    if not previous_lookup:
        return current_rows

    side_fields = {
        "yes": {
            "market": [
                "best_bid",
                "best_ask",
                "spread",
                "bid_depth_topN",
                "ask_depth_topN",
                "ask_depth_total",
                "best_bid_size",
                "best_ask_size",
            ],
            "derived": [
                "entry_price_yes",
                "depth_ratio_yes",
                "signal_edge_round",
                "signal_edge_min",
                "edge_min_yes",
                "edge_score_yes",
            ],
            "ask_key": "best_ask",
            "ask_reason_key": "ask_missing_reason_yes",
        },
        "no": {
            "market": [
                "best_bid_no",
                "best_ask_no",
                "spread_no",
                "bid_depth_topN_no",
                "ask_depth_topN_no",
                "ask_depth_total_no",
                "best_bid_size_no",
                "best_ask_size_no",
            ],
            "derived": [
                "entry_price_no",
                "depth_ratio_no",
                "signal_edge_round_no",
                "signal_edge_min_no",
                "edge_min_no",
                "edge_score_no",
            ],
            "ask_key": "best_ask_no",
            "ask_reason_key": "ask_missing_reason_no",
        },
    }

    merged_rows: List[Dict[str, Any]] = []
    for row in current_rows:
        if not isinstance(row, Mapping):
            merged_rows.append(row)
            continue
        merged = dict(row)
        outcome = str(merged.get("outcome") or "")
        if not outcome:
            merged_rows.append(merged)
            continue
        prev = previous_lookup.get(outcome) or previous_lookup.get(_normalize_outcome_key(outcome))
        if not isinstance(prev, Mapping):
            merged_rows.append(merged)
            continue

        fallback_fields: List[str] = []
        for side in side_fields.values():
            for key in side["market"]:
                if _to_finite_float(merged.get(key)) is not None:
                    continue
                previous_val = _to_finite_float(prev.get(key))
                if previous_val is None:
                    continue
                merged[key] = previous_val
                fallback_fields.append(key)

            for key in side["derived"]:
                if _to_finite_float(merged.get(key)) is not None:
                    continue
                previous_val = _to_finite_float(prev.get(key))
                if previous_val is None:
                    continue
                merged[key] = previous_val
                fallback_fields.append(key)

            ask_key = side["ask_key"]
            ask_reason_key = side["ask_reason_key"]
            ask_val = _to_finite_float(merged.get(ask_key))
            if ask_val is not None:
                merged[ask_reason_key] = None
            else:
                current_reason = str(merged.get(ask_reason_key) or "").strip()
                if not current_reason:
                    prev_reason = str(prev.get(ask_reason_key) or "").strip()
                    if prev_reason:
                        merged[ask_reason_key] = prev_reason

        if fallback_fields:
            merged["snapshot_fallback_fields"] = sorted(set(fallback_fields))
        merged_rows.append(merged)

    return merged_rows


_MARKET_REFRESH_ROW_FIELDS = (
    "best_bid",
    "best_ask",
    "spread",
    "bid_depth_topN",
    "ask_depth_topN",
    "best_bid_no",
    "best_ask_no",
    "spread_no",
    "bid_depth_topN_no",
    "ask_depth_topN_no",
)


def _merge_market_rows_into_payload_rows(
    existing_rows: Any,
    market_rows: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    existing: List[Dict[str, Any]] = []
    if isinstance(existing_rows, list):
        for item in existing_rows:
            if isinstance(item, Mapping):
                existing.append(dict(item))
    market_by_outcome: Dict[str, Dict[str, Any]] = {}
    for item in market_rows:
        if not isinstance(item, Mapping):
            continue
        outcome = str(item.get("outcome") or "")
        if not outcome:
            continue
        row_copy = dict(item)
        market_by_outcome[outcome] = row_copy
        normalized = _normalize_outcome_key(outcome)
        if normalized and normalized not in market_by_outcome:
            market_by_outcome[normalized] = row_copy
    if not existing:
        return [dict(item) for item in market_rows if isinstance(item, Mapping)]

    merged_rows: List[Dict[str, Any]] = []
    seen_keys: Set[str] = set()
    for row in existing:
        outcome = str(row.get("outcome") or "")
        normalized = _normalize_outcome_key(outcome)
        market_row = market_by_outcome.get(outcome) or market_by_outcome.get(normalized)
        row_copy = dict(row)
        if isinstance(market_row, Mapping):
            for key in _MARKET_REFRESH_ROW_FIELDS:
                if key in market_row:
                    row_copy[key] = market_row.get(key)
        merged_rows.append(row_copy)
        if outcome:
            seen_keys.add(outcome)
        if normalized:
            seen_keys.add(normalized)

    for item in market_rows:
        if not isinstance(item, Mapping):
            continue
        outcome = str(item.get("outcome") or "")
        if not outcome:
            continue
        normalized = _normalize_outcome_key(outcome)
        if outcome in seen_keys or (normalized and normalized in seen_keys):
            continue
        merged_rows.append(dict(item))
        seen_keys.add(outcome)
        if normalized:
            seen_keys.add(normalized)
    return merged_rows


def _save_event_run_from_market_refresh(
    conn: sqlite3.Connection,
    run_date: str,
    event_date: str,
    slug: str,
    rows: List[Dict[str, Any]],
    created_at: str,
    event_url: Optional[str] = None,
    title: Optional[str] = None,
    lat: Optional[float] = None,
    lon: Optional[float] = None,
    tz: Optional[str] = None,
) -> None:
    if not slug or not event_date or not rows:
        return
    cur = conn.cursor()
    row_map: Dict[str, Any] = {}
    try:
        cur.execute(
            """
            SELECT *
            FROM event_runs
            WHERE slug = ? AND event_date = ?
            ORDER BY created_at DESC, id DESC
            LIMIT 1
            """,
            (slug, event_date),
        )
        latest = cur.fetchone()
    except sqlite3.Error:
        latest = None
    if latest:
        if isinstance(latest, Mapping):
            row_map = dict(latest)
        else:
            cols = [col[0] for col in (cur.description or [])]
            if cols and isinstance(latest, tuple):
                row_map = {cols[idx]: latest[idx] for idx in range(min(len(cols), len(latest)))}
        payload_obj: Dict[str, Any] = {}
        payload_raw = row_map.get("payload_json")
        if payload_raw:
            try:
                payload_loaded = json.loads(payload_raw)
            except (TypeError, json.JSONDecodeError):
                payload_loaded = None
            if isinstance(payload_loaded, dict):
                payload_obj = dict(payload_loaded)
        payload_obj["rows"] = _merge_market_rows_into_payload_rows(payload_obj.get("rows"), rows)
        payload_obj.setdefault("slug", slug)
        row_map["run_date"] = run_date
        row_map["event_date"] = event_date
        row_map["slug"] = slug
        if event_url:
            row_map["event_url"] = event_url
        if title:
            row_map["title"] = title
        if lat is not None:
            row_map["lat"] = lat
        if lon is not None:
            row_map["lon"] = lon
        if tz:
            row_map["tz"] = tz
        _insert_event_run_with_payload(
            conn,
            row_map,
            json.dumps(payload_obj, ensure_ascii=True),
            created_at,
        )
        return

    payload_obj = {
        "slug": slug,
        "rows": [dict(item) for item in rows if isinstance(item, Mapping)],
    }
    cur.execute(
        """
        INSERT INTO event_runs (
            run_date, event_date, slug, event_url, title, lat, lon, tz,
            payload_json, suggestions_json, created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            run_date,
            event_date,
            slug,
            event_url or f"https://polymarket.com/event/{slug}",
            title or slug,
            lat,
            lon,
            tz,
            json.dumps(payload_obj, ensure_ascii=True),
            "[]",
            created_at,
        ),
    )


def _load_latest_snapshot(
    conn: sqlite3.Connection,
    table: str,
    slug: str,
    event_date: str,
) -> Tuple[Optional[Dict[str, Any]], Optional[Dict[str, Any]], Optional[str], Optional[int]]:
    if not slug or not event_date:
        return None, None, None, None
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT id, payload_json, meta_json, created_at
            FROM {table}
            WHERE slug = ? AND event_date = ?
            ORDER BY created_at DESC, id DESC
            LIMIT 1
            """,
            (slug, event_date),
        )
        row = cur.fetchone()
    except sqlite3.Error:
        return None, None, None, None
    if not row:
        return None, None, None, None
    payload_raw = row[1] if isinstance(row, tuple) else row["payload_json"]
    meta_raw = row[2] if isinstance(row, tuple) else row["meta_json"]
    created_at = row[3] if isinstance(row, tuple) else row["created_at"]
    try:
        payload = json.loads(payload_raw) if payload_raw else None
    except (TypeError, json.JSONDecodeError):
        payload = None
    try:
        meta = json.loads(meta_raw) if meta_raw else None
    except (TypeError, json.JSONDecodeError):
        meta = None
    row_id = row[0] if isinstance(row, tuple) else row["id"]
    return payload, meta, created_at, row_id


def _snapshot_within_window(
    created_at: Optional[str],
    now: datetime,
    window_sec: float,
) -> bool:
    if not created_at:
        return False
    ts = _parse_iso_dt(str(created_at))
    if ts is None:
        return False
    age = (now - ts).total_seconds()
    return age >= 0 and age <= window_sec


def _snapshot_time_delta_ok(
    a: Optional[str],
    b: Optional[str],
    window_sec: float,
) -> bool:
    if not a or not b:
        return False
    ta = _parse_iso_dt(str(a))
    tb = _parse_iso_dt(str(b))
    if ta is None or tb is None:
        return False
    return abs((ta - tb).total_seconds()) <= window_sec


def save_model_snapshot(
    conn: sqlite3.Connection,
    run_date: str,
    event_date: str,
    result: Dict[str, Any],
    meta: Dict[str, Any],
    created_at: str,
) -> None:
    slug = str(result.get("slug") or meta.get("slug") or "")
    if not slug or not event_date:
        return
    payload = json.dumps(to_jsonable_result(result))
    meta_json = json.dumps(meta) if meta else None
    cur = conn.cursor()
    for attempt in range(5):
        try:
            cur.execute(
                """
                INSERT INTO model_snapshots (run_date, event_date, slug, payload_json, meta_json, created_at)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (run_date, event_date, slug, payload, meta_json, created_at),
            )
            return
        except sqlite3.OperationalError as exc:
            if "locked" in str(exc).lower() and attempt < 4:
                time.sleep(0.25 * (attempt + 1))
                continue
            if "locked" in str(exc).lower():
                print(
                    f"[scan_snapshot] save_model_snapshot locked slug={slug} event_date={event_date} error={exc}"
                )
                return
            raise


def save_market_snapshot(
    conn: sqlite3.Connection,
    run_date: str,
    event_date: str,
    slug: str,
    rows: List[Dict[str, Any]],
    meta: Dict[str, Any],
    created_at: str,
) -> None:
    if not slug or not event_date or not rows:
        return
    payload_obj = {"slug": slug, "rows": rows}
    payload = json.dumps(payload_obj)
    meta_json = json.dumps(meta) if meta else None
    cur = conn.cursor()
    for attempt in range(5):
        try:
            cur.execute(
                """
                INSERT INTO market_snapshots (run_date, event_date, slug, payload_json, meta_json, created_at)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (run_date, event_date, slug, payload, meta_json, created_at),
            )
            return
        except sqlite3.OperationalError as exc:
            if "locked" in str(exc).lower() and attempt < 4:
                time.sleep(0.25 * (attempt + 1))
                continue
            if "locked" in str(exc).lower():
                print(
                    f"[scan_snapshot] save_market_snapshot locked slug={slug} event_date={event_date} error={exc}"
                )
                return
            raise


def compose_score_snapshot(
    run_date: str,
    event_date: str,
    slug: str,
    args: argparse.Namespace,
    meta_hint: Optional[Dict[str, Any]] = None,
) -> Tuple[bool, Optional[str]]:
    init_db()
    now = datetime.now(timezone.utc)
    window_sec = _env_float("PM_SCORE_COMPOSE_WINDOW_SEC")
    if window_sec is None or not math.isfinite(window_sec) or window_sec <= 0:
        window_sec = 10800.0
    conn = open_db()
    payload_model, meta_model, created_model, model_id = _load_latest_snapshot(
        conn, "model_snapshots", slug, event_date
    )
    payload_market, meta_market, created_market, market_id = _load_latest_snapshot(
        conn, "market_snapshots", slug, event_date
    )
    conn.close()
    if payload_model is None or payload_market is None:
        return False, "missing_snapshot"
    if not _snapshot_within_window(created_model, now, window_sec):
        return False, "model_snapshot_expired"
    if not _snapshot_within_window(created_market, now, window_sec):
        return False, "market_snapshot_expired"
    if not _snapshot_time_delta_ok(created_model, created_market, window_sec):
        return False, "snapshot_time_mismatch"

    meta = dict(meta_hint or {})
    for source in (meta_model, meta_market):
        if isinstance(source, dict):
            for key, value in source.items():
                if key not in meta or meta.get(key) in (None, ""):
                    meta[key] = value
    if isinstance(payload_model, dict):
        for key in (
            "event_url",
            "title",
            "resolution_source",
            "market_var",
            "market_unit",
            "rounding_rule",
            "city_most_likely_label",
            "city_most_likely_q",
        ):
            if key not in meta or meta.get(key) in (None, ""):
                meta[key] = payload_model.get(key)
    event_url = str(meta.get("event_url") or "")
    if not event_url and slug:
        event_url = f"https://polymarket.com/event/{slug}"
        meta["event_url"] = event_url
    lat = meta.get("lat")
    lon = meta.get("lon")
    tz = meta.get("tz")
    if lat is None or lon is None or not tz:
        return False, "missing_location_meta"

    compose_args = argparse.Namespace(**vars(args))
    compose_args.model_cache_only = True
    compose_args.no_orderbook_fetch = True
    compose_args.no_market_ticks = False
    compose_args.force_model_refresh = False
    compose_args.auto_trade = False
    compose_args.update_models = False
    compose_args.market_refresh_only = False
    compose_args.model_refresh_only = False

    try:
        result = analyze_event(event_url, event_date, float(lat), float(lon), str(tz), compose_args)
    except Exception as exc:
        return False, f"compose_failed {exc}"

    rows = result.get("rows") or []
    if isinstance(rows, list):
        for row in rows:
            if not isinstance(row, dict):
                continue
            best_ask = _to_finite_float(row.get("best_ask"))
            best_ask_no = _to_finite_float(row.get("best_ask_no"))
            q_edge = _to_finite_float(row.get("q_calibrated"))
            if q_edge is None:
                q_edge = _to_finite_float(row.get("q_raw"))
            q_edge_no = _to_finite_float(row.get("q_calibrated_no"))
            if q_edge_no is None:
                q_edge_no = _to_finite_float(row.get("q_raw_no"))
            q_entry = _to_finite_float(row.get("q_entry"))
            q_entry_no = _to_finite_float(row.get("q_entry_no"))
            if best_ask is not None and q_edge is not None:
                row["signal_edge_round"] = q_edge - best_ask
            if best_ask is not None and q_entry is not None:
                row["signal_edge_min"] = q_entry - best_ask
            if best_ask_no is not None and q_edge_no is not None:
                row["signal_edge_round_no"] = q_edge_no - best_ask_no
            if best_ask_no is not None and q_entry_no is not None:
                row["signal_edge_min_no"] = q_entry_no - best_ask_no

    result["skip_market_ticks"] = True
    result["score_composer"] = {
        "model_snapshot_id": model_id,
        "market_snapshot_id": market_id,
        "model_snapshot_at": created_model,
        "market_snapshot_at": created_market,
    }
    archive_run(run_date, event_date, result, [], meta)
    return True, None


def save_market_ticks(
    conn: sqlite3.Connection,
    run_date: str,
    event_date: str,
    result: Dict,
    created_at: str,
) -> None:
    rows = result.get("rows") or []
    slug = str(result.get("slug") or "")
    if not rows or not slug or not event_date:
        return
    date_key = event_date.split("T", 1)[0]
    cur = conn.cursor()

    def _insert_with_retry(params: Tuple[Any, ...]) -> bool:
        for attempt in range(5):
            try:
                cur.execute(
                    """
                    INSERT INTO event_market_ticks (
                        run_date, event_date, slug, outcome, side,
                        best_bid, best_ask, mid, spread,
                        bid_depth_topN, ask_depth_topN, created_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    params,
                )
                return True
            except sqlite3.OperationalError as exc:
                if "locked" not in str(exc).lower() or attempt == 4:
                    print(f"[market_refresh] save_market_ticks locked slug={slug} event_date={date_key} error={exc}")
                    return False
                time.sleep(0.5 * (attempt + 1))
        return False

    for row in rows:
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        for side in ("YES", "NO"):
            if side == "YES":
                best_bid = row.get("best_bid")
                best_ask = row.get("best_ask")
                spread = row.get("spread")
                bid_depth = row.get("bid_depth_topN")
                ask_depth = row.get("ask_depth_topN")
            else:
                best_bid = row.get("best_bid_no")
                best_ask = row.get("best_ask_no")
                spread = row.get("spread_no")
                bid_depth = row.get("bid_depth_topN_no")
                ask_depth = row.get("ask_depth_topN_no")
            if best_bid is None and best_ask is None:
                continue
            mid = None
            if best_bid is not None and best_ask is not None:
                mid = (float(best_bid) + float(best_ask)) / 2.0
            if not _insert_with_retry(
                (
                    run_date,
                    date_key,
                    slug,
                    outcome,
                    side,
                    best_bid,
                    best_ask,
                    mid,
                    spread,
                    bid_depth,
                    ask_depth,
                    created_at,
                ),
            ):
                return


def _load_cached_market_tokens(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
) -> List[Dict[str, Any]]:
    if not slug or not event_date:
        return []
    date_key = event_date.split("T", 1)[0]
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT outcome, yes_token, no_token, outcome_volume, liquidity
            FROM market_tokens
            WHERE slug = ? AND event_date = ?
            """,
            (slug, date_key),
        )
        rows = cur.fetchall()
    except sqlite3.Error:
        return []
    tokens: List[Dict[str, Any]] = []
    for outcome, yes_token, no_token, outcome_volume, liquidity in rows:
        label = str(outcome or "").strip()
        if not label:
            continue
        tokens.append(
            {
                "label": label,
                "yes_token": str(yes_token) if yes_token else None,
                "no_token": str(no_token) if no_token else None,
                "outcome_volume": outcome_volume,
                "liquidity": liquidity,
            }
        )
    return tokens


def _load_cached_market_tokens_latest(
    conn: sqlite3.Connection,
    slug: str,
) -> List[Dict[str, Any]]:
    if not slug:
        return []
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT event_date
            FROM market_tokens
            WHERE slug = ?
            ORDER BY updated_at DESC
            LIMIT 1
            """,
            (slug,),
        )
        row = cur.fetchone()
        if not row:
            return []
        latest_event_date = str(row[0] or "")
        if not latest_event_date:
            return []
    except sqlite3.Error:
        return []
    return _load_cached_market_tokens(conn, slug, latest_event_date)


def _save_cached_market_tokens(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
    outcome_tokens: List[Dict[str, Any]],
    updated_at: str,
) -> None:
    if not slug or not event_date or not outcome_tokens:
        return
    date_key = event_date.split("T", 1)[0]
    cur = conn.cursor()
    for item in outcome_tokens:
        if not isinstance(item, dict):
            continue
        outcome = str(item.get("label") or "").strip()
        if not outcome:
            continue
        yes_token = item.get("yes_token")
        no_token = item.get("no_token")
        vol = to_float(item.get("outcome_volume"))
        liq = to_float(item.get("liquidity"))
        cur.execute(
            """
            INSERT INTO market_tokens (
                slug, event_date, outcome, yes_token, no_token, outcome_volume, liquidity, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(slug, event_date, outcome) DO UPDATE SET
                yes_token=excluded.yes_token,
                no_token=excluded.no_token,
                outcome_volume=excluded.outcome_volume,
                liquidity=excluded.liquidity,
                updated_at=excluded.updated_at
            """,
            (slug, date_key, outcome, yes_token, no_token, vol, liq, updated_at),
        )


def refresh_market_ticks_for_event(
    slug: str,
    event_date: str,
    args: argparse.Namespace,
    event_detail: Optional[Dict[str, Any]] = None,
) -> Tuple[bool, Optional[str], int, Optional[List[Dict[str, Any]]], Optional[str]]:
    if not slug or not event_date:
        return False, "missing_slug_or_date", 0, None, None
    outcome_tokens: List[Dict[str, Any]] = []
    cache_only = False
    if getattr(args, "market_refresh_only", False):
        cache_only = _env_bool("PM_MARKET_REFRESH_CACHE_ONLY", True)
    # Prefer cached tokens to avoid Gamma fan-out/instability in minute-level refresh loops.
    try:
        init_db()
        with open_db() as conn:
            outcome_tokens = _load_cached_market_tokens(conn, slug, event_date)
    except Exception:
        outcome_tokens = []
    if cache_only and not outcome_tokens:
        try:
            init_db()
            with open_db() as conn:
                outcome_tokens = _load_cached_market_tokens_latest(conn, slug)
        except Exception:
            outcome_tokens = []
        if not outcome_tokens:
            return False, "cache_only_missing_tokens", 0, None, None

    if not outcome_tokens:
        if event_detail is None:
            try:
                event_detail = fetch_gamma_event_by_slug(slug)
            except Exception:
                event_detail = None
        if event_detail is not None:
            try:
                outcome_tokens = parse_outcomes_and_tokens_from_event(event_detail)
            except Exception:
                outcome_tokens = []
        if not outcome_tokens:
            try:
                market = fetch_gamma_market_by_slug(slug)
            except Exception:
                market = None
            if market is not None:
                try:
                    outcome_tokens = parse_outcomes_and_tokens(market)
                except Exception:
                    outcome_tokens = []
        if not outcome_tokens:
            # Gamma failed; fall back to latest cached tokens for the slug if available.
            try:
                init_db()
                with open_db() as conn:
                    outcome_tokens = _load_cached_market_tokens_latest(conn, slug)
            except Exception:
                outcome_tokens = []
            if outcome_tokens:
                print(f"[market_refresh] fallback cached tokens slug={slug} event_date={event_date}")
        if outcome_tokens:
            try:
                init_db()
                with open_db() as conn:
                    _save_cached_market_tokens(conn, slug, event_date, outcome_tokens, utc_now_iso())
                    conn.commit()
            except Exception:
                pass
    if not outcome_tokens:
        return False, "missing_outcomes", 0, None, None

    # Market refresh can be very expensive for temperature markets (many outcomes x 2 sides).
    # To keep the "facts/ticks freshness" SSOT moving, we bound fan-out and allow partial refresh.
    max_outcomes = 0
    try:
        max_outcomes = int(getattr(args, "market_refresh_max_outcomes", 0) or 0)
    except Exception:
        max_outcomes = 0
    if max_outcomes < 0:
        max_outcomes = 0
    # For small markets, partial refresh is more confusing than helpful (UI shows YES/NO '—' for skipped buckets).
    # If the number of outcomes is small enough, refresh all outcomes regardless of max_outcomes.
    try:
        refresh_all_max = int(os.environ.get("PM_SCAN_MARKET_REFRESH_ALL_OUTCOMES_MAX", "10") or 0)
    except (TypeError, ValueError):
        refresh_all_max = 10
    if refresh_all_max > 0 and len(outcome_tokens) <= refresh_all_max:
        max_outcomes = 0
    time_budget_sec = 0.0
    try:
        time_budget_sec = float(getattr(args, "market_refresh_time_budget_sec", 0.0) or 0.0)
    except Exception:
        time_budget_sec = 0.0
    if not math.isfinite(time_budget_sec) or time_budget_sec < 0:
        time_budget_sec = 0.0
    # Tighten per-request policy for market refresh so a few bad books don't stall the whole event.
    clob_timeout_sec = 0.0
    try:
        clob_timeout_sec = float(getattr(args, "market_refresh_clob_timeout_sec", 0.0) or 0.0)
    except Exception:
        clob_timeout_sec = 0.0
    if not math.isfinite(clob_timeout_sec) or clob_timeout_sec <= 0:
        clob_timeout_sec = float(_env_float("PM_SCAN_MARKET_REFRESH_CLOB_BOOK_TIMEOUT_SEC") or 3.0)
    if not math.isfinite(clob_timeout_sec) or clob_timeout_sec <= 0:
        clob_timeout_sec = 3.0
    try:
        clob_retries = int(getattr(args, "market_refresh_clob_retries", 0) or 0)
    except Exception:
        clob_retries = 0
    if clob_retries <= 0:
        clob_retries = int(_env_int("PM_SCAN_MARKET_REFRESH_CLOB_BOOK_RETRIES") or 1)
    if clob_retries < 1:
        clob_retries = 1
    if clob_retries > 3:
        clob_retries = 3

    # Prioritize the latest known best candidate (facts SSOT), then liquid outcomes.
    # We include:
    # - event_fact_history.best_outcome (composer's best label)
    # - auto_trade_ssot.main_candidate.outcome (execution candidate label)
    priority_labels: set[str] = set()
    def _add_adjacent_labels(tokens: List[Dict[str, Any]], label: str, radius: int = 2) -> None:
        if not label:
            return
        idx = None
        for i, item in enumerate(tokens):
            if str(item.get("label") or "") == label:
                idx = i
                break
        if idx is None:
            return
        start = max(0, idx - radius)
        end = min(len(tokens), idx + radius + 1)
        for j in range(start, end):
            lbl = str(tokens[j].get("label") or "").strip()
            if lbl:
                priority_labels.add(lbl)
    try:
        init_db()
        with open_db() as conn:
            cur = conn.cursor()
            cur.execute(
                """
                SELECT h.best_outcome, h.fact_json
                FROM event_fact_latest l
                JOIN event_fact_history h ON h.id = l.fact_id
                WHERE l.slug = ? AND l.event_date = ?
                LIMIT 1
                """,
                (slug, event_date),
            )
            row = cur.fetchone()
            if row:
                best_outcome = str(row[0] or "").strip()
                if best_outcome:
                    priority_labels.add(best_outcome)
                    _add_adjacent_labels(outcome_tokens, best_outcome)
                raw_fact = row[1]
                if raw_fact:
                    try:
                        fact = json.loads(raw_fact)
                    except Exception:
                        fact = None
                    if isinstance(fact, dict):
                        ssot = fact.get("auto_trade_ssot")
                        if isinstance(ssot, dict):
                            cand = ssot.get("main_candidate")
                            if isinstance(cand, dict):
                                cand_outcome = str(cand.get("outcome") or "").strip()
                                if cand_outcome:
                                    priority_labels.add(cand_outcome)
                                    _add_adjacent_labels(outcome_tokens, cand_outcome)
            event_date_key = event_date.split("T", 1)[0] if event_date else event_date
            if event_date_key:
                position_min_size = _env_float("PM_SCAN_PRIORITY_POSITION_MIN_SIZE")
                if position_min_size is None or not math.isfinite(position_min_size) or position_min_size < 0:
                    position_min_size = 0.01
                cur.execute(
                    """
                    SELECT outcome
                    FROM edge_trades
                    WHERE slug = ?
                      AND event_date = ?
                      AND COALESCE(position_size, 0) > ?
                    """,
                    (slug, event_date_key, float(position_min_size)),
                )
                for row_pos in cur.fetchall() or []:
                    held_outcome = str(row_pos[0] or "").strip()
                    if held_outcome:
                        priority_labels.add(held_outcome)
    except Exception:
        priority_labels = set()

    def _volume_score(item: Dict[str, Any]) -> float:
        vol = to_float(item.get("outcome_volume"))
        if vol is None or not math.isfinite(vol) or vol < 0:
            return 0.0
        return float(vol)

    # Sort by priority then liquidity/volume.
    sorted_tokens: List[Dict[str, Any]] = sorted(
        [it for it in outcome_tokens if isinstance(it, dict)],
        key=lambda it: (
            0 if str(it.get("label") or "") in priority_labels else 1,
            -_volume_score(it),
            -(to_float(it.get("liquidity")) or 0.0),
        ),
    )
    if max_outcomes > 0 and len(sorted_tokens) > max_outcomes:
        # Ensure we always include priority labels, even if volume is low.
        kept: List[Dict[str, Any]] = []
        for it in sorted_tokens:
            label = str(it.get("label") or "")
            if label and label in priority_labels:
                kept.append(it)
        for it in sorted_tokens:
            if it in kept:
                continue
            kept.append(it)
            if len(kept) >= max_outcomes:
                break
        sorted_tokens = kept

    rows: List[Dict[str, Any]] = []
    # If we fail to obtain *any* bid/ask across all refreshed outcomes (e.g. CLOB 502/timeout),
    # do NOT treat this refresh as success; otherwise minute-level refresh loops can "match" events
    # forever while never updating `event_market_ticks.created_at`, making freshness look stuck.
    any_quote = False
    last_ob_error: Optional[str] = None
    allow_token_remap = _env_bool("PM_SCAN_MARKET_REFRESH_ALLOW_TOKEN_REMAP", True)
    allow_gamma_price_fallback = _env_bool("PM_SCAN_MARKET_REFRESH_ALLOW_GAMMA_PRICE_FALLBACK", True)
    allow_last_tick_fallback = _env_bool("PM_SCAN_MARKET_REFRESH_ALLOW_LAST_TICK_FALLBACK", True)
    token_refresh_attempted: Set[str] = set()
    last_tick_fallback_cache: Dict[Tuple[str, str], Tuple[Optional[float], Optional[float], Optional[float], float, float]] = {}

    def _looks_like_no_orderbook_error(text: str) -> bool:
        lowered = str(text or "").lower()
        if "status=404" in lowered or "orderbook_unavailable" in lowered:
            return True
        if "orderbook" not in lowered:
            return False
        return ("does not exist" in lowered) or ("no orderbook" in lowered)

    def _refresh_token_ids_for_label(outcome_label: str) -> Dict[str, Any]:
        label = str(outcome_label or "").strip()
        if not label:
            return {}
        label_key = _normalize_outcome_key(label)
        if not label_key or label_key in token_refresh_attempted:
            return {}
        token_refresh_attempted.add(label_key)
        remap_gamma_timeout = _env_float("PM_SCAN_MARKET_REFRESH_TOKEN_REMAP_GAMMA_TIMEOUT_SEC")
        if (
            remap_gamma_timeout is None
            or not math.isfinite(remap_gamma_timeout)
            or remap_gamma_timeout <= 0
        ):
            remap_gamma_timeout = min(float(GAMMA_TIMEOUT), 3.0)
        remap_gamma_retries = _env_int("PM_SCAN_MARKET_REFRESH_TOKEN_REMAP_GAMMA_RETRIES")
        if remap_gamma_retries is None or remap_gamma_retries <= 0:
            remap_gamma_retries = 1
        remap_gamma_backoff = _env_float("PM_SCAN_MARKET_REFRESH_TOKEN_REMAP_GAMMA_BACKOFF_SEC")
        if (
            remap_gamma_backoff is None
            or not math.isfinite(remap_gamma_backoff)
            or remap_gamma_backoff < 0
        ):
            remap_gamma_backoff = 0.1
        remap_gamma_bypass_proxy = _env_bool(
            "PM_SCAN_MARKET_REFRESH_TOKEN_REMAP_GAMMA_BYPASS_PROXY",
            False,
        )
        remap_tokens: List[Dict[str, Any]] = []
        try:
            detail = fetch_gamma_event_by_slug(
                slug,
                timeout=remap_gamma_timeout,
                retries=remap_gamma_retries,
                backoff=remap_gamma_backoff,
                bypass_proxy=remap_gamma_bypass_proxy,
            )
        except Exception:
            detail = None
        if detail is not None:
            try:
                remap_tokens = parse_outcomes_and_tokens_from_event(detail)
            except Exception:
                remap_tokens = []
        if not remap_tokens:
            try:
                market = fetch_gamma_market_by_slug(
                    slug,
                    timeout=remap_gamma_timeout,
                    retries=remap_gamma_retries,
                    backoff=remap_gamma_backoff,
                    bypass_proxy=remap_gamma_bypass_proxy,
                )
            except Exception:
                market = None
            if market is not None:
                try:
                    remap_tokens = parse_outcomes_and_tokens(market)
                except Exception:
                    remap_tokens = []
        if not remap_tokens:
            return {}
        try:
            init_db()
            with open_db() as conn:
                _save_cached_market_tokens(conn, slug, event_date, remap_tokens, utc_now_iso())
                conn.commit()
        except Exception:
            pass
        for token_item in remap_tokens:
            if not isinstance(token_item, dict):
                continue
            item_label = _normalize_outcome_key(token_item.get("label"))
            if item_label != label_key:
                continue
            out: Dict[str, Any] = {}
            yes_token = str(token_item.get("yes_token") or "").strip()
            no_token = str(token_item.get("no_token") or "").strip()
            yes_price = to_float(token_item.get("yes_price"))
            no_price = to_float(token_item.get("no_price"))
            if yes_token:
                out["yes_token"] = yes_token
            if no_token:
                out["no_token"] = no_token
            if yes_price is not None and math.isfinite(yes_price):
                out["yes_price"] = float(yes_price)
            if no_price is not None and math.isfinite(no_price):
                out["no_price"] = float(no_price)
            return out
        return {}

    def _fetch_side_quote(
        outcome_label: str,
        item_ref: Dict[str, Any],
        side: str,
    ) -> Tuple[Optional[float], Optional[float], Optional[float], float, float, Optional[str]]:
        side_u = str(side or "").strip().upper()
        token_key = "yes_token" if side_u == "YES" else "no_token"
        price_key = "yes_price" if side_u == "YES" else "no_price"
        token_id = str(item_ref.get(token_key) or "").strip()
        fallback_price = to_float(item_ref.get(price_key))
        if not token_id and allow_token_remap:
            remap = _refresh_token_ids_for_label(outcome_label)
            if remap.get(token_key):
                token_id = str(remap.get(token_key) or "").strip()
                item_ref[token_key] = token_id
            remap_price = to_float(remap.get(price_key))
            if remap_price is not None and math.isfinite(remap_price):
                fallback_price = float(remap_price)
                item_ref[price_key] = fallback_price
        if not token_id:
            return None, None, None, 0.0, 0.0, f"{side_u.lower()}_missing_token"
        try:
            book = fetch_orderbook(
                token_id,
                retries=clob_retries,
                backoff=0.25,
                timeout_sec=clob_timeout_sec,
            )
            (
                best_bid_val,
                best_ask_val,
                spread_val,
                bid_depth_val,
                ask_depth_val,
                _best_bid_size,
                _best_ask_size,
            ) = best_bid_ask_and_depth(book, levels=args.depth_levels)
            return (
                best_bid_val,
                best_ask_val,
                spread_val,
                float(bid_depth_val or 0.0),
                float(ask_depth_val or 0.0),
                None,
            )
        except Exception as exc:
            err_text = str(exc or "")
            is_no_orderbook = _looks_like_no_orderbook_error(err_text)
            if is_no_orderbook and allow_token_remap:
                remap = _refresh_token_ids_for_label(outcome_label)
                new_token = str(remap.get(token_key) or "").strip()
                if new_token and new_token != token_id:
                    token_id = new_token
                    item_ref[token_key] = token_id
                    remap_price = to_float(remap.get(price_key))
                    if remap_price is not None and math.isfinite(remap_price):
                        fallback_price = float(remap_price)
                        item_ref[price_key] = fallback_price
                    try:
                        book = fetch_orderbook(
                            token_id,
                            retries=clob_retries,
                            backoff=0.25,
                            timeout_sec=clob_timeout_sec,
                        )
                        (
                            best_bid_val,
                            best_ask_val,
                            spread_val,
                            bid_depth_val,
                            ask_depth_val,
                            _best_bid_size,
                            _best_ask_size,
                        ) = best_bid_ask_and_depth(book, levels=args.depth_levels)
                        return (
                            best_bid_val,
                            best_ask_val,
                            spread_val,
                            float(bid_depth_val or 0.0),
                            float(ask_depth_val or 0.0),
                            None,
                        )
                    except Exception as retry_exc:
                        err_text = str(retry_exc or err_text)
            if (
                allow_gamma_price_fallback
                and fallback_price is not None
                and math.isfinite(fallback_price)
                and fallback_price > 0
            ):
                return float(fallback_price), float(fallback_price), 0.0, 0.0, 0.0, "gamma_price_fallback"
            if allow_last_tick_fallback:
                cache_key = (str(outcome_label or "").strip(), side_u)
                fallback_tick = last_tick_fallback_cache.get(cache_key)
                if fallback_tick is None:
                    try:
                        init_db()
                        with open_db() as conn:
                            (
                                fb_bid,
                                fb_ask,
                                fb_bid_depth,
                                fb_ask_depth,
                                _prev_bid,
                                _prev_ask,
                                _prev_bid_depth,
                                _prev_ask_depth,
                            ) = _latest_tick_for_outcome(
                                conn,
                                slug,
                                event_date,
                                cache_key[0],
                                side_u,
                            )
                    except Exception:
                        fb_bid = None
                        fb_ask = None
                        fb_bid_depth = None
                        fb_ask_depth = None
                    fb_spread = (
                        max(float(fb_ask) - float(fb_bid), 0.0)
                        if (
                            fb_bid is not None
                            and math.isfinite(fb_bid)
                            and fb_ask is not None
                            and math.isfinite(fb_ask)
                        )
                        else None
                    )
                    fallback_tick = (
                        fb_bid,
                        fb_ask,
                        fb_spread,
                        float(fb_bid_depth or 0.0),
                        float(fb_ask_depth or 0.0),
                    )
                    last_tick_fallback_cache[cache_key] = fallback_tick
                if fallback_tick[0] is not None or fallback_tick[1] is not None:
                    return (
                        fallback_tick[0],
                        fallback_tick[1],
                        fallback_tick[2],
                        fallback_tick[3],
                        fallback_tick[4],
                        "last_tick_fallback",
                    )
            hint = "orderbook_missing" if is_no_orderbook else "orderbook_fetch_failed"
            return None, None, None, 0.0, 0.0, f"{side_u.lower()}_{hint}:{err_text[:120]}"

    t0 = time.monotonic()
    for item in sorted_tokens:
        if time_budget_sec > 0 and (time.monotonic() - t0) >= time_budget_sec and rows:
            break
        label = str(item.get("label") or "")
        yes_token = item.get("yes_token")
        no_token = item.get("no_token")
        if not label:
            continue
        best_bid = None
        best_ask = None
        spread = None
        bid_depth = 0.0
        ask_depth = 0.0
        best_bid_no = None
        best_ask_no = None
        spread_no = None
        bid_depth_no = 0.0
        ask_depth_no = 0.0
        item_mut = item if isinstance(item, dict) else {}
        if yes_token or allow_token_remap:
            (
                best_bid,
                best_ask,
                spread,
                bid_depth,
                ask_depth,
                yes_err,
            ) = _fetch_side_quote(label, item_mut, "YES")
            if yes_err:
                last_ob_error = yes_err
        if no_token or allow_token_remap:
            (
                best_bid_no,
                best_ask_no,
                spread_no,
                bid_depth_no,
                ask_depth_no,
                no_err,
            ) = _fetch_side_quote(label, item_mut, "NO")
            if no_err:
                last_ob_error = no_err
        if (
            best_bid is not None
            or best_ask is not None
            or best_bid_no is not None
            or best_ask_no is not None
        ):
            any_quote = True
        rows.append(
            {
                "outcome": label,
                "best_bid": best_bid,
                "best_ask": best_ask,
                "spread": spread,
                "bid_depth_topN": bid_depth,
                "ask_depth_topN": ask_depth,
                "best_bid_no": best_bid_no,
                "best_ask_no": best_ask_no,
                "spread_no": spread_no,
                "bid_depth_topN_no": bid_depth_no,
                "ask_depth_topN_no": ask_depth_no,
            }
        )
    if not rows:
        return False, "empty_ticks", 0, None, None
    if not any_quote:
        # Preserve a short hint in logs so "freshness stuck" can be diagnosed quickly.
        hint = last_ob_error or "orderbook_unavailable"
        return False, f"no_orderbook_quotes:{hint}", 0, None, None
    result = {"slug": slug, "rows": rows}
    init_db()
    created_at = utc_now_iso()
    title_hint = str((event_detail or {}).get("title") or slug)
    event_url = f"https://polymarket.com/event/{slug}" if slug else ""
    with open_db() as conn:
        save_market_ticks(conn, today_date_str(args.tz), event_date, result, created_at)
        _save_event_run_from_market_refresh(
            conn,
            today_date_str(args.tz),
            event_date,
            slug,
            rows,
            created_at,
            event_url=event_url,
            title=title_hint,
        )
        conn.commit()
    partial = len(rows) < len(outcome_tokens)
    return True, ("partial" if partial else None), len(rows), rows, created_at


def archive_run(
    run_date: str,
    event_date: str,
    result: Dict,
    suggestions: List[Dict],
    meta: Dict,
) -> None:
    init_db()
    date_key = _normalize_event_date(event_date)
    payload_obj = to_jsonable_result(result)
    if _env_bool("PM_Q_CALIBRATED_WRITEBACK", False):
        try:
            _ensure_q_calibrated_writeback(payload_obj)
        except Exception:
            pass
    suggestions_json = json.dumps(suggestions)
    market_closed = meta.get("market_closed")
    market_closed_flag = 1 if market_closed else 0
    created_at = utc_now_iso()
    event_end_utc = meta.get("event_end_utc")
    peak_info: Dict[str, Optional[float]] = {}
    resolution_source = meta.get("resolution_source")
    market_var = meta.get("market_var") or "temperature_2m_max"
    settlement_actual = None
    event_peak_time_utc = None
    if market_closed is not False:
        if (
            resolution_source
            and "wunderground.com/history/daily" in resolution_source
            and market_var == "temperature_2m_max"
        ):
            try:
                peak_info = fetch_wunderground_history_metrics(
                    resolution_source,
                    event_date,
                    "max",
                    meta.get("market_unit"),
                )
            except Exception:
                peak_info = {}
        settlement_actual = peak_info.get("value")
        if settlement_actual is None:
            settlement_actual = fetch_settlement_actual(
                resolution_source,
                event_date,
                market_var,
                meta.get("market_unit"),
                station_id=meta.get("station_id"),
                lat=meta.get("lat"),
                lon=meta.get("lon"),
                tz=meta.get("tz"),
            )
        if peak_info:
            ts = peak_info.get("time_gmt")
            if isinstance(ts, (int, float)):
                event_peak_time_utc = datetime.fromtimestamp(ts, timezone.utc).isoformat()
    city_most_likely_label = result.get("city_most_likely_label")
    city_most_likely_q = result.get("city_most_likely_q")
    corrected_top_bucket_equal = ""
    corrected_top_bucket_auto = ""
    corrected_top_bucket_scenario = ""
    corrected_top_consistency_equal = ""
    corrected_top_consistency_auto = ""
    corrected_top_consistency_scenario = ""
    rows_all = result.get("rows") or []
    models = result.get("models") or []
    rounding_rule = meta.get("rounding_rule") or result.get("rounding_rule")
    market_unit = meta.get("market_unit") or result.get("market_unit")
    lat = meta.get("lat")
    model_members = result.get("model_members") or {}
    if rows_all and models:
        bucket_labels = [bucket.get("outcome") for bucket in rows_all]
        scenario_override = scenario_weights(
            models,
            run_date,
            event_date,
            rounding_rule,
            market_unit,
            bucket_labels,
        )
        weights_equal = resolve_weights(models, "equal", weight_date=run_date)
        weights_auto = resolve_weights(models, "auto", weight_date=run_date)
        weights_scenario = resolve_weights(
            models, "scenario", weights_override=scenario_override, weight_date=run_date
        )
        bias_map = get_recent_model_bias(7, end_date=run_date)
        equal_models = _models_with_complete_rows(rows_all, models)
        weights_equal_bias = resolve_weights(
            equal_models or models, "equal", weight_date=run_date
        )
        weights_scenario_bias = resolve_weights(
            models, "scenario", weights_override=scenario_override, weight_date=run_date
        )

        def _weighted_bias(weights_map: dict) -> Optional[float]:
            if not weights_map:
                return None
            total = 0.0
            acc = 0.0
            for model, weight in weights_map.items():
                try:
                    w = float(weight)
                except (TypeError, ValueError):
                    continue
                entry = bias_map.get(model) or {}
                bias = entry.get("mean")
                try:
                    b = float(bias) if bias is not None else 0.0
                except (TypeError, ValueError):
                    b = 0.0
                total += w
                acc += w * b
            if total <= 0:
                return None
            return acc / total

        bias_equal_c = _weighted_bias(weights_equal_bias)
        bias_scenario_c = _weighted_bias(weights_scenario_bias)
        bias_equal_base = _bias_to_unit(bias_equal_c, market_unit)
        bias_scenario_base = _bias_to_unit(bias_scenario_c, market_unit)
        bias_equal = bias_equal_base
        bias_scenario = bias_scenario_base
        place_bias_map = get_recent_place_bias(7, end_date=run_date)
        place_bias_entry = None
        station_key = (meta.get("station_id") or "").strip()
        city_key = (meta.get("city") or "").strip()
        if station_key:
            place_bias_entry = (place_bias_map.get("station") or {}).get(station_key)
        if place_bias_entry is None and city_key:
            place_bias_entry = (place_bias_map.get("city") or {}).get(city_key)
        if place_bias_entry:
            def _apply_place_bias(base_bias: Optional[float], field: str) -> Optional[float]:
                if base_bias is None:
                    return None
                count = place_bias_entry.get(f"{field}_count") or 0.0
                if count < PLACE_BIAS_MIN_COUNT:
                    return base_bias
                raw = place_bias_entry.get(field)
                place_val = _bias_to_unit(raw, market_unit) if raw is not None else None
                if place_val is None:
                    return base_bias
                alpha = float(count) / (float(count) + PLACE_BIAS_SHRINK_K)
                mixed = alpha * place_val + (1.0 - alpha) * float(base_bias)
                clamp = PLACE_BIAS_CLAMP_C
                if mixed > clamp:
                    mixed = clamp
                elif mixed < -clamp:
                    mixed = -clamp
                return mixed
            bias_equal = _apply_place_bias(bias_equal_base, "equal")
            bias_scenario = _apply_place_bias(bias_scenario_base, "scenario")
        market_label = _top_market_bucket(rows_all)
        shift_cap = None
        if str(market_var or "").startswith("temperature"):
            shift_cap = _estimate_bucket_width(rows_all, rounding_rule, market_unit) * BIAS_SHIFT_CLAMP_RATIO

        def _safe_shift(value: Optional[float]) -> float:
            if value is None:
                return 0.0
            try:
                fval = float(value)
            except (TypeError, ValueError):
                return 0.0
            return fval if math.isfinite(fval) else 0.0

        def _clamp_shift(value: float) -> float:
            if not shift_cap or shift_cap <= 0:
                return value
            if value > shift_cap:
                return shift_cap
            if value < -shift_cap:
                return -shift_cap
            return value

        def _bias_residual(target: Optional[float], base: Optional[float]) -> float:
            if target is None or base is None:
                return 0.0
            try:
                return float(target) - float(base)
            except (TypeError, ValueError):
                return 0.0

        model_bias_unit: Dict[str, float] = {}
        for model in models:
            entry = bias_map.get(model) or {}
            bias_unit = _bias_to_unit(entry.get("mean"), market_unit)
            model_bias_unit[model] = _safe_shift(bias_unit)

        def _build_shift_map(residual: float, apply_model_bias: bool) -> Dict[str, float]:
            shifts: Dict[str, float] = {}
            for model in models:
                base_shift = model_bias_unit.get(model, 0.0) if apply_model_bias else 0.0
                shifts[model] = _clamp_shift(base_shift + residual)
            return shifts

        def _coerce_members(source: Dict[str, Any]) -> Dict[str, np.ndarray]:
            out: Dict[str, np.ndarray] = {}
            for model in models:
                values = source.get(model)
                if values is None:
                    continue
                arr = np.array(values, dtype=float)
                if arr.size == 0:
                    continue
                out[model] = arr
            return out

        def _bucket_rep_value(label: str) -> Optional[float]:
            if not label:
                return None
            return _bucket_expected_value_from_label(label, rounding_rule, lat, event_date)

        def _bucket_distance(a: str, b: str) -> Optional[float]:
            va = _bucket_rep_value(a)
            vb = _bucket_rep_value(b)
            if va is None or vb is None:
                return None
            return abs(va - vb)

        def _consistency(label: str) -> str:
            if not label or not market_label:
                return ""
            return "一致" if label == market_label else "不一致"

        def _top_n_buckets(
            weights_map: Dict[str, float],
            members_by_model: Dict[str, np.ndarray],
            shifts: Optional[Dict[str, float]],
            factor: float,
            n: int = 3,
        ) -> List[Dict[str, float]]:
            if not weights_map or not members_by_model:
                return []
            items = []
            for row in rows_all:
                label = row.get("outcome") or ""
                if not label:
                    continue
                try:
                    spec = parse_outcome_label(label)
                except ValueError:
                    continue
                total_w = 0.0
                acc = 0.0
                for model in models:
                    w = weights_map.get(model, 0.0)
                    if w <= 0:
                        continue
                    values = members_by_model.get(model)
                    if values is None or values.size == 0:
                        continue
                    shift = 0.0
                    if shifts:
                        shift = float(shifts.get(model, 0.0) or 0.0) * factor
                    if shift:
                        values = values - shift
                    q_band = compute_q_band(values, spec, rounding_rule)
                    acc += w * float(q_band.get("q_round") or 0.0)
                    total_w += w
                if total_w <= 0:
                    continue
                q = acc / total_w
                items.append((q, label))
            items.sort(key=lambda x: (-x[0], _bucket_sort_key(x[1])))
            out = []
            for q, label in items[:n]:
                out.append({"label": label, "q": q})
            return out

        def _jump_payload(raw_label: str, corrected_label: str) -> Dict[str, Any]:
            delta = _bucket_distance(raw_label, corrected_label)
            exceed = (
                delta is not None
                and max_jump is not None
                and max_jump > 0
                and delta > max_jump
            )
            return {
                "raw": raw_label,
                "corrected": corrected_label,
                "delta": delta,
                "threshold": max_jump,
                "exceed": exceed,
            }

        members_raw = _coerce_members(model_members)
        max_jump = None
        if str(market_var or "").startswith("temperature"):
            max_jump = _estimate_bucket_width(rows_all, rounding_rule, market_unit) * MAX_TOP_BUCKET_JUMP_RATIO
        residual_equal = _bias_residual(bias_equal, bias_equal_base)
        residual_scenario = _bias_residual(bias_scenario, bias_scenario_base)
        shifts_equal = _build_shift_map(residual_equal, True)
        shifts_scenario = _build_shift_map(residual_scenario, True)
        shifts_auto = _build_shift_map(0.0, False)
        raw_top3_equal = _top_n_buckets(weights_equal, members_raw, shifts_equal, 0.0)
        raw_top3_auto = _top_n_buckets(weights_auto, members_raw, shifts_auto, 0.0)
        raw_top3_scenario = _top_n_buckets(weights_scenario, members_raw, shifts_scenario, 0.0)
        corrected_top3_equal = _top_n_buckets(weights_equal, members_raw, shifts_equal, 1.0)
        corrected_top3_auto = _top_n_buckets(weights_auto, members_raw, shifts_auto, 1.0)
        corrected_top3_scenario = _top_n_buckets(weights_scenario, members_raw, shifts_scenario, 1.0)
        corrected_top_bucket_equal = corrected_top3_equal[0]["label"] if corrected_top3_equal else ""
        corrected_top_bucket_auto = corrected_top3_auto[0]["label"] if corrected_top3_auto else ""
        corrected_top_bucket_scenario = corrected_top3_scenario[0]["label"] if corrected_top3_scenario else ""
        corrected_top_consistency_equal = _consistency(corrected_top_bucket_equal)
        corrected_top_consistency_auto = _consistency(corrected_top_bucket_auto)
        corrected_top_consistency_scenario = _consistency(corrected_top_bucket_scenario)
        raw_label_equal = raw_top3_equal[0]["label"] if raw_top3_equal else ""
        raw_label_auto = raw_top3_auto[0]["label"] if raw_top3_auto else ""
        raw_label_scenario = raw_top3_scenario[0]["label"] if raw_top3_scenario else ""
        payload_obj["bucket_diag"] = {
            "raw_top3": {
                "equal": raw_top3_equal,
                "auto": raw_top3_auto,
                "scenario": raw_top3_scenario,
            },
            "corrected_top3": {
                "equal": corrected_top3_equal,
                "auto": corrected_top3_auto,
                "scenario": corrected_top3_scenario,
            },
            "jump": {
                "equal": _jump_payload(raw_label_equal, corrected_top_bucket_equal),
                "auto": _jump_payload(raw_label_auto, corrected_top_bucket_auto),
                "scenario": _jump_payload(raw_label_scenario, corrected_top_bucket_scenario),
            },
        }
    conn = open_db()
    slug_key = str(meta.get("slug") or result.get("slug") or "")
    previous_rows = _load_latest_payload_rows(conn, slug_key, date_key)
    current_rows = payload_obj.get("rows")
    if isinstance(current_rows, list) and previous_rows:
        payload_obj["rows"] = _merge_rows_preserve_edge_scores(current_rows, previous_rows)
    payload = json.dumps(payload_obj)
    cur = conn.cursor()
    station_id = (meta.get("station_id") or "").strip()
    if station_id and market_var.startswith("temperature") and date_key:
        try:
            is_recent = _station_forecast_is_recent(
                conn, station_id, date_key, STATION_FORECAST_TTL_SEC
            )
        except sqlite3.Error:
            is_recent = False
        if not is_recent:
            forecast = fetch_station_forecast_max(
                date_key,
                market_var,
                meta.get("market_unit"),
                station_id=station_id,
                lat=meta.get("lat"),
                lon=meta.get("lon"),
                tz=meta.get("tz"),
            )
            if forecast and forecast.get("value") is not None:
                save_station_forecast(
                    conn,
                    run_date,
                    date_key,
                    station_id,
                    resolution_source,
                    float(forecast["value"]),
                    meta.get("market_unit"),
                    forecast.get("forecast_time"),
                    forecast.get("forecast_date") or date_key,
                    forecast.get("source"),
                    created_at,
                )
    cur.execute(
        """
        INSERT INTO event_runs (
            run_date, event_date, slug, event_url, title, city, lat, lon, tz,
            location_basis,
            resolution_source, station_id, rounding_rule, market_var, market_unit,
            market_open_at,
            settlement_actual, city_most_likely_label, city_most_likely_q,
            event_peak_time_utc, event_end_utc, market_closed,
            corrected_top_bucket_equal, corrected_top_bucket_auto, corrected_top_bucket_scenario,
            corrected_top_consistency_equal, corrected_top_consistency_auto, corrected_top_consistency_scenario,
            payload_json, suggestions_json, created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            run_date,
            event_date,
            meta.get("slug"),
            meta.get("event_url"),
            meta.get("title"),
            meta.get("city"),
            meta.get("lat"),
            meta.get("lon"),
            meta.get("tz"),
            meta.get("location_basis"),
            meta.get("resolution_source"),
            meta.get("station_id"),
            meta.get("rounding_rule"),
            meta.get("market_var"),
            meta.get("market_unit"),
            meta.get("market_open_at"),
            settlement_actual,
            city_most_likely_label,
            city_most_likely_q,
            event_peak_time_utc,
            event_end_utc,
            market_closed_flag,
            corrected_top_bucket_equal,
            corrected_top_bucket_auto,
            corrected_top_bucket_scenario,
            corrected_top_consistency_equal,
            corrected_top_consistency_auto,
            corrected_top_consistency_scenario,
            payload,
            suggestions_json,
            created_at,
        ),
    )
    if not result.get("skip_market_ticks"):
        save_market_ticks(conn, run_date, event_date, result, created_at)
    if not isinstance(result.get("score_composer"), dict):
        try:
            result_snapshot = dict(result)
            try:
                result_snapshot["rows"] = list(payload_obj.get("rows") or [])
            except Exception:
                pass
            if "bucket_diag" in payload_obj and "bucket_diag" not in result_snapshot:
                result_snapshot["bucket_diag"] = payload_obj.get("bucket_diag")
            if "bucket_diagnostics" in payload_obj and "bucket_diagnostics" not in result_snapshot:
                result_snapshot["bucket_diagnostics"] = payload_obj.get("bucket_diagnostics")
            save_model_snapshot(conn, run_date, date_key, result_snapshot, meta, created_at)
            market_rows: List[Dict[str, Any]] = []
            for row in payload_obj.get("rows") or []:
                if not isinstance(row, Mapping):
                    continue
                outcome = str(row.get("outcome") or "")
                if not outcome:
                    continue
                market_rows.append(
                    {
                        "outcome": outcome,
                        "best_bid": row.get("best_bid"),
                        "best_ask": row.get("best_ask"),
                        "spread": row.get("spread"),
                        "bid_depth_topN": row.get("bid_depth_topN"),
                        "ask_depth_topN": row.get("ask_depth_topN"),
                        "best_bid_no": row.get("best_bid_no"),
                        "best_ask_no": row.get("best_ask_no"),
                        "spread_no": row.get("spread_no"),
                        "bid_depth_topN_no": row.get("bid_depth_topN_no"),
                        "ask_depth_topN_no": row.get("ask_depth_topN_no"),
                    }
                )
            save_market_snapshot(
                conn,
                run_date,
                date_key,
                slug_key,
                market_rows,
                {
                    "slug": slug_key,
                    "event_url": meta.get("event_url") or result_snapshot.get("event_url") or "",
                    "title": meta.get("title") or result_snapshot.get("title") or "",
                    "city": meta.get("city"),
                    "lat": meta.get("lat"),
                    "lon": meta.get("lon"),
                    "tz": meta.get("tz"),
                    "event_end_utc": meta.get("event_end_utc") or "",
                    "market_open_at": meta.get("market_open_at"),
                },
                created_at,
            )
        except Exception:
            pass
    conn.commit()
    conn.close()


