def _insert_event_run_with_payload(
    conn: sqlite3.Connection,
    base_row: Mapping[str, Any],
    payload_json: str,
    created_at: str,
) -> None:
    cur = conn.cursor()
    base_map = dict(base_row) if not isinstance(base_row, dict) else base_row
    cur.execute("PRAGMA table_info(event_runs)")
    cols = [row[1] for row in cur.fetchall() if row[1] != "id"]
    values = []
    for col in cols:
        if col == "payload_json":
            values.append(payload_json)
        elif col == "created_at":
            values.append(created_at)
        else:
            values.append(base_map.get(col))
    placeholders = ",".join("?" for _ in cols)
    col_list = ",".join(cols)
    cur.execute(
        f"INSERT INTO event_runs ({col_list}) VALUES ({placeholders})",
        values,
    )


def _recompute_signal_edges_in_rows(rows: List[Dict[str, Any]]) -> bool:
    changed = False
    for row in rows:
        if not isinstance(row, dict):
            continue
        best_ask = _to_finite_float(row.get("best_ask"))
        best_ask_no = _to_finite_float(row.get("best_ask_no"))
        q_cal = _to_finite_float(row.get("q_calibrated"))
        q_raw = _to_finite_float(row.get("q_raw"))
        q_entry = _to_finite_float(row.get("q_entry"))
        q_cal_no = _to_finite_float(row.get("q_calibrated_no"))
        if q_cal_no is None and q_cal is not None:
            q_cal_no = 1.0 - q_cal
            row["q_calibrated_no"] = q_cal_no
        q_raw_no = _to_finite_float(row.get("q_raw_no"))
        if q_raw_no is None and q_raw is not None:
            q_raw_no = 1.0 - q_raw
            row["q_raw_no"] = q_raw_no
        if q_raw is None and q_raw_no is not None:
            q_raw = 1.0 - q_raw_no
            row["q_raw"] = q_raw
        if q_cal is None and q_cal_no is not None:
            q_cal = 1.0 - q_cal_no
            row["q_calibrated"] = q_cal
        if q_raw_no is None and q_raw is not None:
            q_raw_no = 1.0 - q_raw
        q_entry_no = _to_finite_float(row.get("q_entry_no"))
        if q_entry_no is None and q_cal_no is not None:
            q_entry_no = q_cal_no
            row["q_entry_no"] = q_entry_no
        if q_entry_no is None and q_raw_no is not None:
            q_entry_no = q_raw_no
            row["q_entry_no"] = q_entry_no
        if q_entry is None and q_cal is not None:
            q_entry = q_cal
            row["q_entry"] = q_entry
        if q_entry is None and q_raw is not None:
            q_entry = q_raw
            row["q_entry"] = q_entry
        q_edge = q_cal if q_cal is not None else q_raw
        q_edge_no = q_cal_no if q_cal_no is not None else q_raw_no

        if best_ask is not None and q_edge is not None:
            new_val = q_edge - best_ask
            prev = row.get("signal_edge_round")
            if _to_finite_float(prev) != new_val:
                row["signal_edge_round"] = new_val
                changed = True
        if best_ask is not None and q_entry is not None:
            new_val = q_entry - best_ask
            prev = row.get("signal_edge_min")
            if _to_finite_float(prev) != new_val:
                row["signal_edge_min"] = new_val
                changed = True
        if best_ask_no is not None and q_edge_no is not None:
            new_val = q_edge_no - best_ask_no
            prev = row.get("signal_edge_round_no")
            if _to_finite_float(prev) != new_val:
                row["signal_edge_round_no"] = new_val
                changed = True
        if best_ask_no is not None and q_entry_no is not None:
            new_val = q_entry_no - best_ask_no
            prev = row.get("signal_edge_min_no")
            if _to_finite_float(prev) != new_val:
                row["signal_edge_min_no"] = new_val
                changed = True
    return changed


def _writeback_q_calibrated_payload(payload: Dict[str, Any]) -> Tuple[bool, str]:
    if not isinstance(payload, dict):
        return False, "invalid_payload"
    rows = payload.get("distribution")
    if rows is None:
        rows = payload.get("rows")
    if not isinstance(rows, list) or not rows:
        return False, "no_rows"
    for row in rows:
        if not isinstance(row, dict):
            continue
        val = to_float(row.get("q_calibrated"))
        if val is not None and math.isfinite(val):
            return False, "has_q_calibrated"
    tmp_payload: Dict[str, Any] = {"rows": rows}
    prov = payload.get("fact_provenance")
    if isinstance(prov, dict):
        tmp_payload["fact_provenance"] = dict(prov)
    ok = _ensure_q_calibrated_writeback(tmp_payload)
    if not ok:
        return False, "platt_unavailable_or_no_raw"
    if "distribution" in payload:
        payload["distribution"] = rows
    else:
        payload["rows"] = rows
    if "fact_provenance" in tmp_payload:
        payload["fact_provenance"] = tmp_payload["fact_provenance"]
    return True, ""


def writeback_q_calibrated_for_run_date(
    run_date: str,
    limit: int = 0,
) -> Dict[str, Any]:
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing"}
    run_date_key = _normalize_date_key(run_date)
    if not run_date_key:
        return {"ok": False, "error": "no_run_date"}
    q_platt = _load_q_platt_calibration(Q_PLATT_DAYS)
    if not isinstance(q_platt, dict) or not q_platt.get("enabled"):
        return {"ok": False, "error": "platt_unavailable"}
    init_db()
    conn = open_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT id, slug, event_date, fact_json
            FROM event_fact_history
            WHERE run_date = ?
            ORDER BY fact_as_of DESC, id DESC
            """,
            (run_date_key,),
        )
    except sqlite3.OperationalError:
        conn.close()
        return {"ok": False, "error": "db_error"}
    seen: set[Tuple[str, str]] = set()
    total = 0
    updated = 0
    skipped_has = 0
    skipped_no_rows = 0
    skipped_no_platt = 0
    for row in cur.fetchall():
        slug = str(row["slug"] or "")
        event_date = str(row["event_date"] or "")
        if not slug or not event_date:
            continue
        key = (slug, event_date)
        if key in seen:
            continue
        seen.add(key)
        total += 1
        if limit and updated >= limit:
            break
        raw = row["fact_json"]
        if not raw:
            skipped_no_rows += 1
            continue
        try:
            payload = json.loads(raw)
        except (TypeError, json.JSONDecodeError):
            skipped_no_rows += 1
            continue
        if not isinstance(payload, dict):
            skipped_no_rows += 1
            continue
        ok, reason = _writeback_q_calibrated_payload(payload)
        if not ok:
            if reason == "has_q_calibrated":
                skipped_has += 1
            elif reason == "platt_unavailable_or_no_raw":
                skipped_no_platt += 1
            else:
                skipped_no_rows += 1
            continue
        new_payload = json.dumps(payload, ensure_ascii=True)
        cur.execute(
            "UPDATE event_fact_history SET fact_json = ? WHERE id = ?",
            (new_payload, int(row["id"])),
        )
        updated += 1
    conn.commit()
    conn.close()
    return {
        "ok": True,
        "run_date": run_date_key,
        "total": total,
        "updated": updated,
        "skipped_has_q_calibrated": skipped_has,
        "skipped_no_rows": skipped_no_rows,
        "skipped_platt_or_raw": skipped_no_platt,
        "limit": limit,
    }


def backfill_signal_edges_for_event_runs(
    market_var_like: str = "temperature%",
    limit: int = 0,
) -> Dict[str, Any]:
    init_db()
    conn = open_db()
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute(
        """
        SELECT e.*
        FROM event_runs e
        JOIN (
          SELECT slug, event_date, MAX(created_at) AS max_created
          FROM event_runs
          WHERE market_var LIKE ?
          GROUP BY slug, event_date
        ) l
          ON e.slug = l.slug AND e.event_date = l.event_date AND e.created_at = l.max_created
        WHERE e.market_var LIKE ?
        ORDER BY e.event_date, e.slug
        """,
        (market_var_like, market_var_like),
    )
    rows = cur.fetchall()
    total = 0
    updated = 0
    skipped = 0
    for row in rows:
        if limit and updated >= limit:
            break
        total += 1
        payload_raw = row["payload_json"]
        if not payload_raw:
            skipped += 1
            continue
        try:
            payload = json.loads(payload_raw)
        except (TypeError, json.JSONDecodeError):
            skipped += 1
            continue
        rows_payload = payload.get("rows")
        if not isinstance(rows_payload, list):
            skipped += 1
            continue
        rows_copy = [dict(item) if isinstance(item, Mapping) else item for item in rows_payload]
        changed = _recompute_signal_edges_in_rows(rows_copy)
        if not changed:
            skipped += 1
            continue
        payload["rows"] = rows_copy
        new_payload = json.dumps(payload)
        _insert_event_run_with_payload(conn, row, new_payload, utc_now_iso())
        updated += 1
    conn.commit()
    conn.close()
    return {"total": total, "updated": updated, "skipped": skipped}

