def load_latest_weights() -> Dict[str, float]:
    init_db()
    conn = open_db()
    cur = conn.cursor()
    cur.execute(
        "SELECT weight_date FROM model_weights ORDER BY weight_date DESC LIMIT 1"
    )
    row = cur.fetchone()
    conn.close()
    return load_weights_for_date(row[0] if row else None)


def load_weights_for_date(weight_date: Optional[str]) -> Dict[str, float]:
    if not weight_date:
        return {}
    init_db()
    conn = open_db()
    cur = conn.cursor()
    cur.execute(
        "SELECT model, weight FROM model_weights WHERE weight_date = ?",
        (weight_date,),
    )
    data = {r[0]: float(r[1]) for r in cur.fetchall()}
    conn.close()
    return data


def _normalize_weights(weights: dict, models: list) -> Optional[dict]:
    if not weights:
        return None
    missing = [m for m in models if m not in weights]
    if missing:
        return None
    try:
        total = sum(float(weights[m]) for m in models)
    except (TypeError, ValueError):
        return None
    if total <= 0:
        return None
    if any(float(weights[m]) < 0 for m in models):
        return None
    return {m: float(weights[m]) / total for m in models}


def _normalize_weights_partial(weights: dict, models: list) -> Optional[dict]:
    if not weights:
        return None
    try:
        values = {m: float(weights.get(m, 0.0)) for m in models}
    except (TypeError, ValueError):
        return None
    if any(v < 0 for v in values.values()):
        return None
    total = sum(values.values())
    if total <= 0:
        return None
    return {m: values[m] / total for m in models}


def resolve_weights(
    models: list,
    weighting: str,
    weights_override: Optional[dict] = None,
    weight_date: Optional[str] = None,
) -> dict:
    if not models:
        return {}
    if weighting == "scenario":
        override = _normalize_weights(weights_override or {}, models)
        if override:
            return override
        w = 1.0 / len(models)
        return {m: w for m in models}
    if weighting == "auto":
        override = _normalize_weights_partial(weights_override or {}, models)
        if override:
            return override
        stored = _normalize_weights_partial(load_weights_for_date(weight_date), models)
        if stored:
            return stored
        stored_latest = _normalize_weights_partial(load_latest_weights(), models)
        if stored_latest:
            return stored_latest
        recent = _normalize_weights_partial(get_recent_hit_weights(7, end_date=weight_date), models)
        if recent:
            bias = get_recent_model_bias(7, end_date=weight_date)
            return _apply_bias_penalty(recent, bias)
        w = 1.0 / len(models)
        bias = get_recent_model_bias(7, end_date=weight_date)
        return _apply_bias_penalty({m: w for m in models}, bias)
    w = 1.0 / len(models)
    return {m: w for m in models}


